window.HB_TR["joshua"]["ur"]=["1۔ اب موسیٰ کی موت کے بعد، جو خداوند کا خادم تھا، ایسا ہوا کہ خداوند نے یشوع، نون کے بیٹے، موسیٰ کے وزیر سے کہا، \n2۔ موسیٰ، میرا بندہ مر چکا ہے؛ اب اٹھو، اس اردن کے پار چلو، تم اور یہ سب لوگ، اس زمین کی طرف جاؤ جو میں انہیں دیتا ہوں، {حتیٰ کہ} بنی اسرائیل کو بھی۔ \n3۔ ہر وہ جگہ جہاں تمہارے پاؤں کی تلواں قدم رکھے گی، جو میں نے تمہیں دی ہے، جیسا کہ میں نے موسیٰ سے کہا۔ \n4۔ بیابان اور اس لبنان سے یہاں تک کہ عظیم دریا تک، دریائے فرات تک، حتیوں کی ساری زمین، اور عظیم سمندر تک سورج کے غروب ہونے تک، تمہارا ساحل ہوگا۔ \n5. کوئی بھی تمہارے سامنے تمہاری زندگی کے تمام دن کھڑا نہیں ہو سکتا: جیسے میں موسیٰ کے ساتھ تھا، {ویسے} میں تمہارے ساتھ ہوں گا: میں تمہیں مایوس نہیں کروں گا، نہ تمہیں چھوڑوں گا۔ \n6۔ مضبوط اور حوصلہ رکھو: کیونکہ تم اس قوم کو وراثت کے لیے وہ زمین تقسیم کرو گے، جسے میں ان کے آباؤ اجداد سے دینے کا وعدہ کرتا ہوں۔ {اس کے لیے...: یا پھر تم اس قوم کو زمین کا وارث بناؤ گے، وغیرہ}\n7۔ صرف تم مضبوط اور بہادر بنو تاکہ تم وہ تمام قانون کے مطابق عمل کر سکو جو میرے خادم موسیٰ نے تمہیں حکم دیا تھا: اس سے نہ دائیں ہاتھ اور نہ ہی بائیں طرف مڑو، تاکہ جہاں بھی جاؤ کامیاب ہو سکو۔ {خوشحالی: یا، دانائی سے کرو}\n8۔ یہ قانون کی کتاب تمہارے منہ سے نہیں نکلے گی؛ لیکن تم دن رات اس میں غور کرو گے تاکہ تم اس میں لکھی ہوئی ہر چیز کے مطابق عمل کرو: تب تم اپنا راستہ خوشحال کرو گے، اور پھر تمہیں اچھی کامیابی ملے گی۔ {کیا...: یا، دانائی سے کام کرو}\n9۔ کیا میں نے تمہیں حکم نہیں دیا؟ مضبوط اور حوصلہ رکھو؛ ڈرو مت، نہ مایوس ہو، کیونکہ خداوند تمہارا خدا تمہارے ساتھ ہے جہاں بھی تم جاؤ۔ \n10۔ پھر یشوع نے قوم کے افسران کو حکم دیا اور کہا، \n11۔ لشکر سے گزر کر لوگوں کو حکم دو، کہو، اپنی خوراک تیار کرو؛ کیونکہ تین دن کے اندر تم اس اردن کے پار جا کر اس زمین پر قبضہ کرنے کے لیے جاؤ گے، جو خداوند تمہارا خدا تمہیں عطا کرتا ہے۔ \n12۔ اور روبینیوں سے، گادیوں کو، اور منسی کے آدھے قبیلے سے کہا، یشوع نے کہا، \n13۔ اس کلام کو یاد رکھو جو موسیٰ، خداوند کے بندے نے تمہیں حکم دیا تھا، کہ خداوند تمہارا خدا تمہیں سکون دیا ہے اور تمہیں یہ زمین عطا کی ہے۔ \n14۔ تمہاری بیویاں، تمہارے ننھے بچے اور تمہارے مویشی، اس زمین میں رہیں گے جو موسیٰ نے تمہیں اس طرف اردن پر دی تھی؛ لیکن تم اپنے بھائیوں کے سامنے مسلح، تمام بہادر مردوں کے سامنے گزرو گے اور ان کی مدد کرو گے؛ {مسلح: عبرانی۔ پانچ کے ذریعے جمع کیا گیا}\n15۔ جب تک خداوند تمہارے بھائیوں کو آرام نہ دے دے، جیسا کہ {اس نے تمہیں} دیا، اور وہ بھی اس زمین پر قبضہ کر لیں جو خداوند تمہارا خدا انہیں دیتا ہے: تب تم اپنی ملکیت کی زمین میں واپس جاؤ گے، اور اس سے لطف اندوز ہو جاؤ گے، جو موسیٰ خداوند کے خادم نے تمہیں اس طرف اردن کے طلوع آفتاب کی طرف دی تھی۔ \n16۔ اور انہوں نے یشوع کو جواب دیا، کہا، جو کچھ بھی تم ہمیں حکم دے گا وہ ہم کریں گے، اور جہاں بھی تم بھیجو گے، ہم جائیں گے۔ \n17۔ جیسا کہ ہم نے ہر چیز میں موسیٰ کی بات سنی، ویسے ہی ہم تیری سنیں گے: صرف خداوند تیرا خدا تیرے ساتھ ہو، جیسا کہ وہ موسیٰ کے ساتھ تھا۔ \n18۔ جو بھی آپ کے حکم کی خلاف بغاوت کرے اور آپ کی ہر بات میں نہ مانے جو آپ اسے حکم دیتے ہیں، اسے قتل کر دیا جائے گا: صرف مضبوط اور اچھے بہادر بنو۔","1۔ اور یشوع، نون کا بیٹا، شتیم سے دو آدمیوں کو خفیہ طور پر جاسوسی کے لیے بھیجا، اور کہا، جاؤ زمین دیکھو، یہاں تک کہ یریحو بھی۔ اور وہ گئے، اور ایک طوائف، جس کا نام راحاب تھا، کے گھر میں داخل ہوئے اور وہاں ٹھہر گئے۔ {بھیجا: یا، بھیجا تھا} {رہائش: عبرانی۔ لی}\n2۔ اور یریحو کے بادشاہ کو بتایا گیا کہ دیکھو، یہاں رات کو بنی اسرائیل کے لوگ آئے تاکہ ملک کی تلاش کریں۔ \n3۔ اور یریحو کے بادشاہ نے راحاب کو بھیجا، کہا، جو لوگ تمہارے پاس آئے ہیں اور جو تمہارے گھر میں داخل ہوئے ہیں، انہیں باہر لے آؤ، کیونکہ وہ پورے ملک کی تلاش کے لیے آئے ہیں۔ \n4۔ اور عورت نے دونوں مردوں کو لے کر چھپا دیا، اور یوں کہا، میرے پاس لوگ آئے، لیکن میں نہیں جانتا کہ وہ کہاں سے آئے تھے: \n5۔ اور جب دروازہ بند ہوا تو جب اندھیرا تھا، لوگ باہر نکل گئے: جہاں لوگ جاتے تھے، میں نہیں جانتا تھا: جلدی سے ان کے پیچھے جاؤ؛ کیونکہ تم انہیں پکڑ لو گے۔ \n6۔ لیکن اس نے انہیں گھر کی چھت پر لے جا کر فلیکس کے ڈنٹھلوں سے چھپا دیا، جو اس نے چھت پر ترتیب سے رکھے تھے۔ \n7۔ اور آدمیوں نے ان کے پیچھے اردن کی طرف راستوں تک پیچھا کیا، اور جیسے ہی جو ان کے پیچھے آئے وہ باہر نکل گئے، انہوں نے دروازہ بند کر دیا۔ \n8۔ اور جب وہ لٹکے، وہ ان کے پاس چھت پر آ گئی؛ \n9۔ اور اس نے مردوں سے کہا، میں جانتی ہوں کہ خداوند نے تمہیں زمین دی ہے، اور تمہارا خوف ہم پر نازل ہو گیا ہے، اور زمین کے تمام باشندے تمہاری وجہ سے بے ہوش ہو گئے ہیں۔ {مدھم: عبرانی۔ پگھلاؤ}\n10۔ کیونکہ ہم نے سنا ہے کہ خداوند نے تمہارے لیے بحر احمر کا پانی خشک کیا، جب تم مصر سے نکلے؛ اور تم نے اموریوں کے دو بادشاہوں کے ساتھ کیا کیا، جو اردن کے دوسری طرف تھے، سیحون اور اوگ، جنہیں تم نے مکمل طور پر تباہ کر دیا۔ \n11. اور جیسے ہی ہم نے یہ سب سنا، ہمارے دل پگھل گئے، اور کسی انسان میں مزید ہمت باقی نہ رہی، تمہاری وجہ سے: کیونکہ خداوند تمہارا خدا، وہ آسمان پر اور نیچے زمین میں خدا ہے۔ {کیا وہاں...: عبرانی۔ اٹھا}\n12۔ اب میں تم سے دعا کرتا ہوں، خداوند کی قسم کھاؤ، چونکہ میں نے تمہیں مہربانی دی ہے، کہ تم بھی میرے والد کے گھرانے پر مہربانی کرو گے اور مجھے ایک سچا نشان دو گے: \n13. اور یہ کہ تم میرے باپ، میری ماں، میرے بھائی، بہنوں اور ان سب کچھ کو زندہ بچاؤ گے جو ان کے پاس ہے، اور ہماری جانوں کو موت سے بچاؤ گے۔ \n14۔ اور مردوں نے جواب دیا، ہماری جان تمہارے بدلے میں، اگر تم یہ ہمارا معاملہ نہ کہو۔ اور جب خداوند ہمیں زمین دے گا، تب ہم تمہارے ساتھ مہربانی اور سچائی سے پیش آئیں گے۔ {کیونکہ...: عبرانی۔ تمہاری موت کے بجائے}\n15۔ پھر اس نے انہیں کھڑکی سے رسی کے ذریعے نیچے اتارا: کیونکہ اس کا گھر شہر کی دیوار پر تھا، اور وہ دیوار پر رہتی تھی۔ \n16۔ اور اس نے ان سے کہا، تم پہاڑ پر چلو، ورنہ پیچھا کرنے والے تم سے مل جائیں گے؛ اور تین دن وہاں چھپ جاؤ، جب تک کہ پیچھا کرنے والے واپس نہ آ جائیں: اور پھر تم اپنی راہ پر چلو۔ \n17۔ اور مردوں نے اس سے کہا، ہم اس قسم سے بے قصور ہوں گے جو تم نے ہم سے قسم لی ہے۔ \n18۔ دیکھو، {جب} ہم زمین میں آئیں گے، تو تم اس سرخ دھاگے کی لکیر کو اس کھڑکی میں باندھو گے جس سے تم نے ہمیں نیچے اتارا تھا: اور تم اپنے باپ، اپنی ماں، اپنے بھائیوں کو، اور اپنے والد کے تمام گھرانے کو اپنے گھر لے آؤ گے۔ {لے آؤ: عبرانی۔ جمع کرو}\n19۔ اور یہ ہوگا کہ جو بھی تمہارے گھر کے دروازے سے باہر سڑک پر جائے گا، اس کا خون اس کے سر پر ہوگا، اور ہم بے گناہ ہوں گے: اور جو بھی تمہارے ساتھ گھر میں ہوگا، اس کا خون ہمارے سر پر ہوگا، اگر اس پر کوئی ہاتھ ہو۔ \n20۔ اور اگر تم یہ ہمارا معاملہ کہہ دو، تو ہم تمہاری قسم سے آزاد ہو جائیں گے جو تم نے ہم سے قسم کھائی ہے۔ \n21۔ اور اس نے کہا، تمہارے الفاظ کے مطابق، ایسا ہی ہو۔ اور اس نے انہیں بھیج دیا، اور وہ روانہ ہو گئے: اور اس نے کھڑکی میں سرخ لکیر باندھ دی۔ \n22۔ اور وہ گئے، اور پہاڑ پر آئے، اور وہاں تین دن رہے، یہاں تک کہ پیچھا کرنے والے واپس آ گئے: اور پیچھا کرنے والے پورے راستے میں تلاش کرتے رہے، مگر انہیں نہ ملا۔ \n23۔ تو دونوں آدمی واپس آئے، پہاڑ سے نیچے اترے، گزر گئے، اور نون کے بیٹے یشوع کے پاس آئے اور اسے ان سب باتوں کو بتایا جو ان پر ہوئیں: \n24۔ اور انہوں نے یشوع سے کہا، واقعی خداوند نے ساری زمین ہمارے ہاتھوں میں دے دی ہے؛ کیونکہ ملک کے تمام باشندے بھی ہماری وجہ سے بے ہوش ہو جاتے ہیں۔ {مدھم: عبرانی۔ پگھلاؤ}","1۔ اور یشوع صبح سویرے اٹھا؛ اور وہ شتیم سے نکل گئے، اور اردن آئے، وہ اور تمام بنی اسرائیل، اور وہاں ٹھہر گئے اس سے پہلے کہ وہ گزر جائیں۔ \n2۔ اور تین دن بعد ہوا کہ افسران میزبان کے ذریعے گزر گئے؛ \n3۔ اور انہوں نے لوگوں کو حکم دیا، کہا، جب تم خداوند اپنے خدا کے عہد کا صندوق اور لاوی کے کاہنوں کو دیکھو گے جو اسے اٹھائے ہوئے ہیں، تو تم اپنی جگہ سے ہٹ جاؤ اور اس کے پیچھے جاؤ۔ \n4۔ پھر بھی تم اور اس کے درمیان تقریبا دو ہزار ہاتھ کا فاصلہ ہوگا: اس کے قریب مت آؤ تاکہ تم جان سکو کہ تمہیں کس راستے سے جانا ہے: کیونکہ تم نے پہلے تک {یہ} راستہ عبور نہیں کیا۔ {اب تک: عبرانی۔ کل سے، اور تیسرے دن سے}\n5۔ اور یشوع نے لوگوں سے کہا، اپنے آپ کو پاک کرو، کیونکہ کل خداوند تم میں معجزے کرے گا۔ \n6۔ اور یشوع نے کاہنوں سے کہا، عہد کا صندوق اٹھاؤ اور لوگوں کے سامنے چلے جاؤ۔ اور انہوں نے عہد کا صندوق اٹھایا اور لوگوں کے سامنے چلے گئے۔ \n7۔ اور خداوند نے یشوع سے کہا، آج میں تمہیں پورے اسرائیل کی نظر میں جلال بخشوں گا، تاکہ وہ جان سکیں کہ جیسے میں موسیٰ کے ساتھ تھا، {ویسے} میں تمہارے ساتھ ہوں گا۔ \n8۔ اور تم ان کاہنوں کو حکم دو گے جو عہد نامہ کا صندوق اٹھائے ہوئے ہیں، اور کہو گے، جب تم اردن کے پانی کے کنارے پہنچو گے، تو اردن میں کھڑے رہو گے۔ \n9۔ اور یشوع نے بنی اسرائیل سے کہا، یہاں آؤ، اور خداوند تمہارے خدا کے کلام سنو۔ \n10۔ اور یشوع نے کہا، اس طرح تم جان لو گے کہ زندہ خدا تمہارے درمیان ہے، اور وہ ہمیشہ کنعانیوں، حتیوں، حویوں، پیریزیوں، گرغاشیوں، اموری اور یبوسیوں کو تمہارے سامنے سے نکال دے گا۔ \n11۔ دیکھو، زمین کے خداوند کے عہد کا صندوق تمہارے سامنے اردن میں آ رہا ہے۔ \n12۔ اب تم بارہ آدمیوں کو اسرائیل کے قبائل سے نکالو، ہر قبیلے سے ایک آدمی نکالو۔ \n13۔ اور یہ اس وقت ہو جائے گا جب ان کاہنوں کے قدموں کے تلوے جو خداوند کے صندوق کو اٹھائے ہوئے ہیں، اردن کے پانیوں میں آرام کریں گے، {کہ} اردن کے پانی اوپر سے آنے والے پانی سے کٹ جائیں گے؛ اور وہ ایک ڈھیر پر کھڑے ہوں گے۔ \n14۔ اور جب لوگ اپنے خیموں سے نکل کر اردن کے اوپر سے گزرے، اور وہ پادری جو لوگوں کے سامنے عہد کا صندوق اٹھائے ہوئے تھے، وہاں سے گزرے؛ \n15۔ اور جب وہ لوگ جو صندوق کو ننگے تھے اردن پہنچے، اور کاہنوں کے پاؤں جو صندوق رکھتے تھے پانی کے کنارے میں ڈبو دیے گئے، (کیونکہ اردن اپنی تمام کناروں کو فصل کے وقت بھر دیتا ہے،)\n16۔ کہ جو پانی اوپر سے آتا تھا وہ شہر آدم سے بہت دور ایک ڈھیر پر کھڑا ہو گیا، جو زرطان کے کنارے واقع ہے: اور جو لوگ میدان کے سمندر کی طرف آئے، یہاں تک کہ نمکین سمندر بھی، ناکام ہو گئے، اور لوگ یریحو کے سامنے سے گزر گئے۔ \n17۔ اور وہ کاہنوں نے جو خداوند کے عہد نامے کا صندوق اٹھائے تھے، اردن کے بیچ خشک زمین پر مضبوطی سے کھڑے رہے، اور تمام بنی اسرائیل خشک زمین پر گزر گئے، یہاں تک کہ تمام لوگ اردن کے پار پاک ہو گئے۔","1۔ اور جب سب لوگ پاک ہو گئے اور اردن کے پار گزر گئے، تو خداوند نے یشوع سے کہا، \n2۔ تم بارہ آدمیوں کو لوگوں میں سے نکالو، ہر قبیلے سے ایک آدمی نکالو، \n3۔ اور انہیں حکم دو، کہو، اردن کے بیچ سے نکلو، جہاں پادریوں کے قدم مضبوط تھے، بارہ پتھر لے جاؤ، اور انہیں اپنے ساتھ لے جاؤ، اور انہیں رہائش گاہ میں چھوڑ دو، جہاں تم آج رات قیام کرو گے۔ \n4۔ پھر یشوع نے بارہ مردوں کو، جنہیں اس نے بنی اسرائیل میں سے تیار کیا تھا، ہر قبیلے سے ایک آدمی کو بلایا: \n5۔ اور یشوع نے ان سے کہا، خداوند تمہارے خدا کے تابوت کے سامنے اردن کے بیچ چلے جاؤ، اور اپنے ہر آدمی کو اس کے کندھے پر ایک پتھر اٹھا لو، جیسا کہ بنی اسرائیل کے قبائل کی تعداد کے مطابق ہے: \n6. تاکہ یہ آپ کے درمیان ایک نشانی ہو، {کہ} جب آپ کے بچے آنے والے وقت میں {اپنے باپ} سے پوچھیں، کہ آپ ان پتھروں سے کیا مراد لیتے ہیں؟ {وقت کے ساتھ...: عبرانی۔ کل کے لیے}\n7۔ پھر تم انہیں جواب دو گے، کہ اردن کے پانی خداوند کے عہد کے صندوق کے سامنے کاٹ دیے گئے تھے؛ جب وہ اردن کے اوپر سے گزرا، اردن کے پانی کاٹ دیے گئے: اور یہ پتھر بنی اسرائیل کے لیے ہمیشہ یادگار رہیں گے۔ \n8۔ اور بنی اسرائیل نے یشوع کے حکم کے مطابق عمل کیا، اور اردن کے بیچ سے بارہ پتھر اٹھا لیے، جیسا کہ خداوند نے یشوع سے کہا تھا، بنی اسرائیل کے قبائل کی تعداد کے مطابق، اور انہیں اپنے ساتھ لے گئے جہاں وہ ٹھہرے تھے، اور وہاں رکھ دیے۔ \n9۔ اور یشوع نے اردن کے بیچ میں بارہ پتھر لگائے، اس جگہ جہاں ان کاہنوں کے پاؤں کھڑے تھے جو عہد نامہ کا صندوق رکھتے تھے: اور وہ آج تک وہاں ہیں۔ \n10۔ کیونکہ وہ کاہن، جو صندوق کو تھامے تھے، اردن کے بیچ کھڑے تھے، جب تک سب کچھ مکمل نہ ہو گیا کہ خداوند نے یشوع کو حکم دیا کہ وہ لوگوں سے بات کرے، جیسا کہ موسیٰ نے یشوع کو حکم دیا تھا: اور لوگ جلدی سے گزر گئے۔ \n11۔ اور ایسا ہوا جب تمام لوگ پاک ہو گئے، تو خداوند کا تابوت اور پادریوں نے لوگوں کی موجودگی میں عبور کیا۔ \n12۔ اور روبن کے بیٹے، گاد کے بچے اور منسی قبیلے کا آدھا حصہ اسرائیل کے بچوں کے سامنے مسلح ہو کر گزرے، جیسا کہ موسیٰ نے ان سے کہا: \n13۔ تقریبا چالیس ہزار لوگ جنگ کے لیے تیار خداوند کے سامنے جنگ کے لیے روانہ ہوئے، یریحو کے میدانوں میں۔ {تیار: یا، تیار مسلح}\n14۔ اس دن خداوند نے یشوع کو تمام اسرائیل کی نظر میں عظمت دی؛ اور وہ اس سے ڈرتے رہے، جیسے موسیٰ سے اس کی زندگی کے تمام دنوں میں ڈرتے تھے۔ \n15۔ اور خداوند نے یشوع سے کہا، \n16۔ ان کاہنوں کو حکم دو جو شہادت کا تابوت رکھتے ہیں، کہ وہ اردن سے آئیں۔ \n17۔ یشوع نے کاہنوں کو حکم دیا اور کہا، اردن سے باہر آؤ۔ \n18۔ اور ایسا ہوا، جب خداوند کے عہد کا صندوق اٹھائے ہوئے کاہنوں کو اردن کے بیچ سے نکالا گیا، {اور} کاہنوں کے قدموں کے تلوے خشک زمین کی طرف اٹھا دیے گئے، تو اردن کا پانی اپنی جگہ واپس آ گیا، اور اس کے تمام کناروں پر بہنے لگا، جیسا کہ پہلے کیا تھا۔ {اٹھایا گیا...: عبرانی۔ اٹھایا گیا} {بہتا: عبرانی۔ چلا}\n19۔ اور لوگ پہلے مہینے کے دسویں دن اردن سے نکلے، اور اریحو کی مشرقی سرحد پر گلگل میں خیمہ زن ہو گئے۔ \n20۔ اور وہ بارہ پتھر، جو انہوں نے اردن سے نکالے تھے، یشوع نے گلگل میں پھینکا۔ \n21۔ اور اس نے بنی اسرائیل سے کہا، جب تمہارے بچے آنے والے وقت میں اپنے باپوں سے پوچھیں گے، اور کہا، ان پتھر کا کیا مطلب ہے؟ {وقت پر...: عبرانی۔ کل کے لیے}\n22۔ پھر تم اپنے بچوں کو بتاؤ گے، کہہ دو، اسرائیل اس اردن کے پار خشکی زمین پر آیا۔ \n23۔ کیونکہ خداوند تمہارے خدا نے اردن کے پانی کو تمہارے سامنے سے خشک کر دیا، یہاں تک کہ تم پر چڑھ گئے، جیسے خداوند تمہارے خدا نے بحیرہ احمر کے ساتھ کیا، جسے اس نے ہمارے سامنے سے خشک کیا، یہاں تک کہ ہم چلے گئے: \n24۔ تاکہ زمین کے تمام لوگ خداوند کے ہاتھ کو جان سکیں، کہ وہ {عظیم} ہے: تاکہ تم ہمیشہ کے لیے اپنے خداوند خدا سے ڈرو۔ {ہمیشہ کے لیے: عبرانی تمام دن}","1۔ اور ایسا ہوا جب اموری کے تمام بادشاہ، جو اردن کے مغرب میں تھے، اور کنعانیوں کے تمام بادشاہوں نے، جو سمندر کے کنارے تھے، سنا کہ خداوند نے اردن کے پانیوں کو بنی اسرائیل کے سامنے سے خشک کر دیا ہے، یہاں تک کہ ہم گزر گئے، تو ان کے دل پگھل گئے، اور ان میں روح باقی نہ رہی، بنی اسرائیل کی وجہ سے۔ \n2۔ اس وقت خداوند نے یشوع سے کہا، تیز چھریاں بناؤ، اور بنی اسرائیل کو دوسری بار ختنہ کرو۔ {تیز...: یا، چقماق کے چاقو}\n3۔ اور یشوع نے اس کے لیے تیز چھریاں بنائیں، اور بنی اسرائیل کو ختنہ کیا جو کھالوں کی پہاڑی پر تھا۔ {تیز...: یا، چقماق کے چاقو} {پہاڑی...: یا، گبیع-ہارلوت}\n4۔ اور یہی وجہ ہے کہ یشوع نے ختنہ کیا: مصر سے نکلنے والے تمام لوگ، جو مرد تھے، حتیٰ کہ تمام جنگی لوگ، ویسے بھی مصر سے نکلنے کے بعد صحرا میں مر گئے۔ \n5۔ اب تمام لوگ جو باہر نکلے تھے، ختنہ ہو چکے تھے: لیکن وہ سب لوگ جو ویسان میں پیدا ہوئے تھے، جب وہ مصر سے نکلے تو انہوں نے ختنہ نہیں کیا تھا۔ \n6۔ کیونکہ بنی اسرائیل چالیس سال ویرانے میں چلتے رہے، یہاں تک کہ مصر سے نکلنے والے تمام لوگ جو جنگ کے لوگ تھے، ختم ہو گئے، کیونکہ انہوں نے خداوند کی آواز نہیں مانی: جس سے خداوند نے قسم کھائی کہ وہ انہیں وہ زمین نہیں دکھائے گا، جو خداوند نے ان کے آباؤ اجداد سے قسم کھائی تھی کہ وہ ہمیں دے گا، ایک ایسی زمین جو دودھ اور شہد سے بہتی ہے۔ \n7۔ اور ان کے بچے، جنہیں اس نے ان کی جگہ پالا، انہیں یشوع نے ختنہ کیا: کیونکہ وہ ختنہ نہیں ہوئے تھے، کیونکہ انہوں نے انہیں ختنہ نہیں کیا تھا۔ \n8۔ اور جب انہوں نے سب لوگوں کا ختنہ کر لیا، تو وہ کیمپ میں اپنی جگہوں پر ٹھہر گئے، جب تک کہ وہ مکمل نہ ہو گئے۔ {انہوں نے...: عبرانی۔ لوگوں نے ختنہ کروانے کا انجام طے کر لیا تھا}\n9۔ اور خداوند نے یشوع سے کہا، آج میں نے تم سے مصر کی ملامت اتار دی ہے۔ اسی لیے آج تک اس جگہ کا نام گلگل کہلاتا ہے۔ {گلگل: یہ ہے رولنگ}\n10۔ اور بنی اسرائیل گلگل میں خیمہ زن ہوئے اور مہینے کے چودہویں دن یریحو کے میدانوں میں عید فسح منایا۔ \n11۔ اور انہوں نے فسح کے بعد کل زمین کے پرانے اناج سے کھایا، بغیر خمیر کے کیک اور اسی دن پیاسا مکئی کھایا۔ \n12۔ اور کل جب انہوں نے زمین کے پرانے اناج سے کھا لیا تو منا بند ہو گیا؛ نہ ہی بنی اسرائیل کے پاس من تھی؛ لیکن اس سال انہوں نے کنعان کی زمین کے پھل سے کھایا۔ \n13۔ اور جب یشوع یریحو کے پاس تھا، تو اس نے اپنی آنکھیں اٹھائیں اور دیکھا، اور دیکھا کہ ایک آدمی اس کے سامنے کھڑا تھا، اس کے ہاتھ میں تلوار نکالی ہوئی تھی، اور یشوع اس کے پاس گیا اور کہا، کیا تم ہمارے لیے ہو یا ہمارے دشمنوں کے لیے؟ \n14۔ اور اس نے کہا، نہیں؛ لیکن اب میں خداوند کے لشکر کا سردار ہوں۔ اور یشوع زمین پر گر پڑا، عبادت کی، اور اس سے کہا، میرے رب نے اپنے خادم سے کیا کہا؟ {کپتان: یا، شہزادہ}\n15۔ اور خداوند کے لشکر کے سردار نے یشوع سے کہا، اپنا جوتا اپنے پاؤں سے اتار دو؛ کیونکہ جس جگہ پر تم کھڑے ہو وہ مقدس ہے۔ اور یشوع نے ایسا کیا۔","1. اب یریحو کو اسرائیل کے بچوں کی وجہ سے سختی سے بند کر دیا گیا: کوئی باہر نہیں گیا، اور کوئی اندر نہیں آیا۔ {تھا...: عبرانی۔ خاموش رہا، اور خاموش رہا}\n2۔ اور خداوند نے یشوع سے کہا، دیکھو، میں نے تیرے ہاتھ میں یریحو اور اس کے بادشاہ کو دے دیا ہے، {اور} بہادر مردوں کو۔ \n3۔ اور تم شہر کو گھیر لو گے، تمام جنگجوؤں، {اور} شہر کے گرد ایک بار چکر لگاؤ گے۔ یوں تم چھ دن گزارو گے۔ \n4۔ اور سات پادری صندوق کے سامنے مینڈوں کے سینگوں کے سات بگل اٹھائیں گے: اور ساتویں دن تم شہر کو سات بار گھیرو گے، اور پادری بگل سے بجائیں گے۔ \n5۔ اور یہ ہوگا کہ جب وہ مینڈھے کے سینگ سے لمبا دھماکہ کریں گے، {اور} جب تم بگل کی آواز سنو گے، تو تمام لوگ زور دار آواز میں پکار اٹھیں گے؛ اور شہر کی دیوار گر جائے گی، اور لوگ ہر آدمی اس کے سامنے سیدھے اوپر چڑھ جائیں گے۔ {چپٹان: عبرانی۔ اس کے نیچے}\n6۔ اور نون کے بیٹے یشوع نے کاہنوں کو بلایا اور کہا، عہد کا صندوق اٹھاؤ، اور سات پادریوں کو خداوند کے صندوق کے سامنے مینڈوں کے سینگوں کے سات بگل اٹھانے دو۔ \n7۔ اور اس نے لوگوں سے کہا، آگے بڑھو اور شہر کو گھیر لو، اور جو مسلح ہے وہ خداوند کے تابوت کے سامنے گزرے۔ \n8۔ اور جب یشوع نے لوگوں سے بات کی، تو سات پادری جو مینڈوں کے سینگ کے سات شیپور اٹھائے ہوئے تھے، خداوند کے سامنے گزرے اور بگل بجائے: اور خداوند کے عہد کا صندوق ان کے پیچھے آیا۔ \n9۔ اور مسلح لوگ ان پادریوں کے سامنے گئے جنہوں نے بگل بجائے، اور انعام صندوق کے بعد آیا، {کاہن} جاری رہے، اور بگل بجا رہے تھے۔ {انعام: عبرانی۔ جمع کرنے والا لشکر}\n10۔ اور یشوع نے لوگوں کو حکم دیا تھا، کہ تم اپنی آواز سے نہ چلاؤ، نہ شور مچاؤ، نہ ہی تمہارے منہ سے کوئی لفظ نکلے گا، جب تک کہ میں تمہیں چیخنے کا حکم نہ دوں؛ تب تم چیخو۔ {کوئی بھی آواز...: عبرانی۔ تمہاری آواز سنی جائے}\n11۔ تو خداوند کا صندوق شہر کے گرد گھوم گیا، ایک بار اس کے گرد گھومتا رہا: اور وہ کیمپ میں آئے، اور کیمپ میں ٹھہر گئے۔ \n12۔ اور یشوع صبح سویرے اٹھا، اور کاہنوں نے خداوند کا صندوق اٹھایا۔ \n13۔ اور سات پادری سات مینڈوں کے سینگوں کے بگل لے کر خداوند کے صندوق کے سامنے مسلسل چلتے رہے، اور بگل بجاتے رہے، اور مسلح لوگ ان کے سامنے گئے؛ لیکن انعام خداوند کے صندوق کے بعد آیا، {کاہن} چل رہے تھے اور بگل بجا رہے تھے۔ \n14۔ اور دوسرے دن انہوں نے شہر کو ایک بار گھیر لیا، اور کیمپ میں واپس آئے: یوں انہوں نے چھ دن گزارے۔ \n15۔ اور ساتویں دن ایسا ہوا کہ وہ صبح سویرے اٹھے، اور اسی طرح سات بار شہر کا چکر لگایا: صرف اسی دن انہوں نے شہر کو سات بار گھیر لیا۔ \n16۔ اور یہ ساتویں بار ہوا، جب کاہنوں نے بگل بجائے، یشوع نے لوگوں سے کہا، چلاؤ؛ کیونکہ خداوند نے تمہیں شہر دیا ہے۔ \n17۔ اور شہر پر لعنت ہوگی، {حتی} اور اس میں موجود سب لوگ، خداوند کے لیے: صرف راحاب بدکار زندہ رہے گی، وہ اور جو سب اس کے ساتھ گھر میں ہیں، کیونکہ اس نے ہمارے بھیجے ہوئے پیغامبر کو چھپایا تھا۔ {لعنتی: یا، وقف شدہ}\n18. اور تم کسی بھی طرح چیز سے بچتے ہو، کہیں تم خود کو نہ بنا لو، جب تم چیز کو چھین لو گے، اور اسرائیل کے کیمپ کو لعنت بنا کر اسے پریشان کر دو گے۔ {لعنت: یا، وفادار} {لعنت: یا، وفادار}\n19۔ لیکن تمام چاندی، سونا، اور پیتل اور لوہے کے برتن خداوند کے لیے وقف کیے گئے ہیں: وہ خداوند کے خزانے میں آئیں گے۔ {تقدیس: عبرانی۔ پاکیزگی}\n20۔ تو جب {کاہنوں} نے بگل بجایا تو لوگوں نے چیخ ماری: اور جب لوگوں نے بگل کی آواز سنی، اور لوگوں نے زور سے چیخ ماری، تو دیوار گر گئی، اور لوگ شہر میں چلے گئے، ہر آدمی اس کے سامنے کھڑا ہو گیا، اور انہوں نے شہر پر قبضہ کر لیا۔ {ہموار: عبرانی۔ اس کے نیچے}\n21. اور انہوں نے شہر کی ہر چیز کو مکمل طور پر تباہ کر دیا، مرد اور عورت، جوان اور بوڑھے، بیل، بھیڑ اور گدھا، تلوار کے کنارے سے۔ \n22۔ لیکن یشوع نے ان دو آدمیوں سے کہا جنہوں نے دیہات کی جاسوسی کی تھی، اس بدکار عورت کے گھر جاؤ، اور وہاں سے عورت اور اس کے سب کچھ باہر لے آؤ، جیسا کہ تم اس سے قسم کھاتے ہو۔ \n23۔ اور جو نوجوان جاسوس تھے، اندر گئے، اور راحاب، اس کے باپ، اس کی ماں، اور اس کے بھائیوں اور جو کچھ اس کے پاس تھا اسے باہر نکالا؛ اور انہوں نے اس کے تمام رشتہ داروں کو باہر نکالا، اور انہیں اسرائیل کے کیمپ کے بغیر چھوڑ دیا۔ {رشتہ دار: عبرانی۔ خاندان}\n24۔ اور انہوں نے شہر کو آگ سے جلا دیا، اور اس میں جو کچھ بھی تھا: صرف چاندی، سونا، اور پیتل اور لوہے کے برتن، جو انہوں نے خداوند کے گھر کے خزانے میں رکھ دیے۔ \n25۔ اور یشوع نے راحاب کو زندہ بچایا، اور اس کے والد کے گھرانے کو، اور جو کچھ اس کے پاس تھا؛ اور وہ آج تک اسرائیل میں رہتی ہے؛ کیونکہ اس نے وہ پیغام رساں چھپا دیے جو یشوع نے یریحو کی جاسوسی کے لیے بھیجے تھے۔ \n26۔ اور یشوع نے اس وقت {ان} کی قسم دی، کہنے پر، خدا کے سامنے جو اٹھے اور اس شہر یریحو کی تعمیر کرے گا، لعنت ہو: وہ اس کی بنیاد اپنے پہلے بیٹے میں رکھے گا، اور اپنے سب سے چھوٹے {بیٹے} میں اس کے دروازے قائم کرے گا۔ \n27۔ تو خداوند یشوع کے ساتھ تھا؛ اور اس کی شہرت پورے ملک میں پھیل گئی۔","1۔ لیکن بنی اسرائیل نے چیز میں گناہ کیا: کیونکہ آچان، کرمی کا بیٹا، زبدی کا بیٹا، زراہ کا بیٹا، یہوداہ قبیلے سے، نے چیز کو چھین لیا: اور خداوند کا غصہ بنی اسرائیل کے خلاف بھڑک اٹھا۔ {آچان: جسے آخار بھی کہا جاتا ہے} {زبدی: جسے زمری بھی کہا جاتا ہے}\n2۔ اور یشوع نے یریحو سے آدمیوں کو عائی بھیجا، جو بیت ہیون کے ساتھ واقع ہے، بیت ھل کے مشرقی کنارے پر، اور ان سے کہا، اوپر جاؤ اور ملک دیکھو۔ اور وہ لوگ اوپر گئے اور عائی کو دیکھا۔ \n3۔ اور وہ یشوع کے پاس واپس آئے، اور اسے کہا، تمام لوگ اوپر نہ جائیں؛ بلکہ دو یا تین ہزار آدمیوں کو اوپر جا کر عائی کو مارنے دو؛ {اور} سب لوگوں کو وہاں محنت کرنے پر مجبور نہ کرو؛ کیونکہ وہ صرف چند ہی ہیں۔ {تقریبا...: عبرانی۔ تقریبا دو ہزار آدمی، یا تقریبا تین ہزار آدمی}\n4۔ تو وہاں تقریبا تین ہزار آدمی آئے، اور وہ آئی کے لوگوں کے سامنے بھاگ گئے۔ \n5۔ اور عائی کے لوگوں نے تقریبا چھتیس آدمیوں کو مارا، کیونکہ انہوں نے انہیں دروازے کے سامنے {حتیٰ کہ} شیباریم تک پیچھا کیا، اور نیچے جاتے ہوئے انہیں مار ڈالا: یوں لوگوں کے دل پگھل گئے اور پانی کی طرح بن گئے۔ {میں...: یا، موراد میں}\n6۔ اور یشوع نے اپنے کپڑے پھاڑ دیے، اور خداوند کے صندوق کے سامنے منہ کے بل زمین پر گر گیا، یہاں تک کہ شام ہو گئی، اس نے اور اسرائیل کے بزرگوں نے ان کے سروں پر مٹی ڈال دی۔ \n7۔ اور یشوع نے کہا، اے خداوند خدا، تو نے اس قوم کو اردن کے پار کیوں لایا تاکہ ہمیں اموریوں کے ہاتھوں میں دے دے، اور ہمیں تباہ کر دے؟ کاش ہم خدا سے مطمئن ہوتے، اور اردن کے دوسری طرف رہتے ہوتے! \n8. اے خداوند، میں کیا کہوں جب اسرائیل اپنے دشمنوں کے سامنے پیٹھ موڑ لے! {پیٹھ کی آوازیں: عبرانی۔ گردنیں}\n9۔ کیونکہ کنعانی اور زمین کے تمام باشندے اس کی بات سنیں گے، اور ہمیں گھیر لیں گے، اور ہمارا نام زمین سے مٹا دیں گے: اور تم اپنے عظیم نام کے ساتھ کیا کرو گے؟ \n10۔ اور خداوند نے یشوع سے کہا، اٹھو؛ تو اس طرح اپنے چہرے پر کیوں لیٹا ہو؟ {جھوٹ: عبرانی۔ گرا}\n11۔ اسرائیل نے گناہ کیا ہے، اور انہوں نے بھی میرے عہد کی خلاف ورزی کی ہے جس کا میں نے انہیں حکم دیا تھا: کیونکہ انہوں نے چیز کو بھی چھین لیا ہے، چوری کی ہے، دھوکہ بھی دیا ہے، اور اسے اپنی چیزوں میں بھی رکھ دیا ہے۔ \n12۔ اسی لیے بنی اسرائیل اپنے دشمنوں کے سامنے کھڑے نہ ہو سکے، {بلکہ} اپنے دشمنوں کے سامنے پیٹھ موڑ لی، کیونکہ وہ تھے: اور میں بھی تمہارے ساتھ نہیں رہوں گا، جب تک کہ تم اپنے اندر سے لوگوں کو تباہ نہ کر دو۔ \n13۔ اٹھو، لوگوں کو پاک کرو اور کہو، کل تک اپنے آپ کو پاک کرو، کیونکہ یہی فرماتا ہے اسرائیل کے خدا، {اے اسرائیل، تیرے درمیان ایک لعنت زدہ چیز ہے} تم اپنے دشمنوں کے سامنے کھڑے نہیں ہو سکتے، جب تک تم اس لعنتی چیز کو اپنے درمیان سے نہ چھین لو۔ \n14۔ لہٰذا صبح تم اپنے قبیلوں کے مطابق لایا جائے گا: اور یہ ہوگا، {کہ} وہ قبیلہ جسے خداوند لے گا وہ خاندانوں کے مطابق ہوگا؛ اور وہ خاندان جسے خداوند لے گا، وہ گھروں میں آئے گا؛ اور وہ گھرانہ جسے خداوند لے گا، وہ انسان بہ انسان آئے گا۔ \n15۔ اور یہ ہوگا کہ جو چیز کے ساتھ لیا جائے گا، اسے آگ میں جلایا جائے گا، وہ اور اس کے پاس جو کچھ بھی ہے: کیونکہ اس نے خداوند کے عہد کی خلاف ورزی کی ہے، اور کیونکہ اس نے اسرائیل میں حماقت کی ہے۔ {حماقت: یا، برائی}\n16۔ تو یشوع صبح سویرے اٹھا اور اپنے قبیلوں کے ذریعے اسرائیل کو لے آیا؛ اور یہوداہ قبیلہ لے لیا گیا: \n17۔ اور وہ یہوداہ کے خاندان کو لے آیا؛ اور اس نے زارہیوں کے خاندان کو ایک ایک کر کے لایا؛ اور زبدی کو لے جایا گیا: \n18۔ اور اس نے اپنے گھرانے کے آدمی کو ایک کر کے لایا؛ اور آچان، کارمی کا بیٹا، زبدی کا بیٹا، زراہ کا بیٹا، یہوداہ قبیلے سے، گرفتار ہو گیا۔ \n19۔ اور یشوع نے آچان سے کہا، میرے بیٹے، میں دعا کرتا ہوں کہ خداوند اسرائیل کے خدا کو جلال دے، اور اس سے اعتراف کرو؛ اور اب مجھے بتاؤ کہ تم نے کیا کیا ہے؛ مجھ سے اسے نہ چھپا۔ \n20۔ اور آچان نے یشوع کو جواب دیا اور کہا، \"واقعی میں نے اسرائیل کے خداوند خدا کے خلاف گناہ کیا ہے، اور اس طرح میں نے ایسا کیا: \n21۔ جب میں نے مال غنیمت کے درمیان ایک خوبصورت بابلی لباس، دو سو شیکل چاندی، اور پچاس شیکل وزن کا سونا کا ٹکڑا دیکھا، تو میں نے ان کی خواہش کی اور انہیں لے لیا؛ اور دیکھو، وہ زمین میں میرے خیمے کے بیچ چھپے ہوئے ہیں، اور اس کے نیچے چاندی بھی۔ {ویج: عبرانی زبان}\n22۔ تو یشوع نے پیغامبر بھیجے، اور وہ خیمے کی طرف دوڑے؛ اور دیکھو، وہ خیمے میں چھپا ہوا تھا، اور اس کے نیچے چاندی بھی۔ \n23۔ اور انہوں نے انہیں خیمے کے بیچ سے نکالا، اور یشوع اور تمام بنی اسرائیل کے پاس لے گئے، اور انہیں خداوند کے سامنے رکھ دیا۔ {رکھا: عبرانی۔ ڈالا}\n24۔ اور یشوع اور اس کے ساتھ تمام اسرائیل نے زرح کے بیٹے اچان، چاندی، لباس، سونے کا ٹکڑا اور اس کے بیٹے، اپنی بیٹیاں، اپنے بیل، گدھے، بھیڑیں، خیمہ اور جو کچھ اس کے پاس تھا، لے کر انہیں آخور کی وادی لے گئے۔ \n25۔ اور یشوع نے کہا، تم نے ہمیں کیوں پریشان کیا؟ خداوند آج تمہیں پریشان کرے گا۔ اور تمام اسرائیل نے اسے پتھر مارے اور آگ سے جلا دیے، جب انہوں نے انہیں پتھروں سے مارا تھا۔ \n26۔ اور انہوں نے آج تک اس پر پتھروں کا بڑا ڈھیر کھڑا کیا۔ تو خداوند نے اپنے غصے کی شدت سے منہ موڑ لیا۔ اسی لیے اس جگہ کا نام آج تک آخور کی وادی کہلاتا ہے۔ {آخور: یعنی، مصیبت}","1۔ اور خداوند نے یشوع سے کہا، نہ ڈرو، نہ ڈرو: تمام جنگی لوگوں کو اپنے ساتھ لے جاؤ، اور اٹھو، عائی کے پاس چلو: دیکھو، میں نے تیری ہاتھ میں آئی کا بادشاہ، اس کا لوگ، اس کا شہر اور اس کی زمین دے دی ہے: \n2۔ اور تم آئی اور اس کے بادشاہ کے ساتھ ویسا ہی کرو گے جیسا تم نے یریحو اور اس کے بادشاہ کے ساتھ کیا: صرف اس کا مال اور اس کے مویشیوں کو اپنے لیے شکار سمجھو گے: اس کے پیچھے شہر کے لیے گھات لگاؤ گے۔ \n3۔ یوں یشوع اور تمام جنگی لوگ آے کے خلاف کھڑے ہوئے، اور یشوع نے تیس ہزار بہادر آدمیوں کو چن کر رات کو بھیج دیا۔ \n4۔ اور اس نے انہیں حکم دیا، کہا، دیکھو، تم شہر کے سامنے انتظار کرو گے، {حتیٰ کہ} شہر کے پیچھے بھی: شہر سے زیادہ دور نہ جاؤ، لیکن سب تیار ہو جاؤ: \n5۔ اور میں، اور وہ سب لوگ جو میرے ساتھ ہیں، شہر کی طرف بڑھیں گے: اور جب وہ ہمارے خلاف نکلیں گے، جیسا کہ پہلے تھا، ہم ان کے سامنے بھاگ جائیں گے، \n6۔ (کیونکہ وہ ہمارے پیچھے آئیں گے) جب تک ہم انہیں شہر سے نہ نکال لیں؛ کیونکہ وہ کہیں گے، وہ ہم سے پہلے کی طرح بھاگ جائیں گے: اس لیے ہم ان سے پہلے بھاگ جائیں گے۔ {کھینچا: عبرانی۔ کھینچا}\n7۔ پھر تم گھات سے اٹھو گے، اور شہر پر قبضہ کرو گے، کیونکہ خداوند تمہارا خدا اسے تمہارے ہاتھ میں دے گا۔ \n8۔ اور جب تم شہر پر قبضہ کر لو گے، تو تم شہر کو آگ لگا دو گے: خداوند کے حکم کے مطابق تم ایسا کرو گے۔ دیکھو، میں نے تمہیں حکم دیا ہے۔ \n9۔ یوں یشوع نے انہیں باہر بھیجا: اور وہ گھات لگا کر بیٹھل اور عائی کے درمیان، عائی کے مغربی کنارے پر قیام کے لیے چلے گئے، لیکن یشوع اس رات لوگوں کے درمیان ٹھہر گیا۔ \n10۔ اور یشوع صبح سویرے اٹھا، لوگوں کو گنا، اور وہ اور اسرائیل کے بزرگوں نے لوگوں کے سامنے عائی کی طرف بڑھا۔ \n11۔ اور تمام لوگ، {یہاں تک کہ جنگ کے لوگ} بھی، جو اس کے ساتھ تھے، اوپر گئے، قریب آئے، شہر کے سامنے آئے، اور آئی کے شمالی کنارے پر کھڑے ہو گئے: اب ان اور آئی کے درمیان ایک وادی تھی۔ \n12۔ اور اس نے تقریبا پانچ ہزار آدمیوں کو لے کر انہیں شہر کے مغربی جانب بیت ایل اور آئی کے درمیان گھات میں لگا دیا۔ {of...: or, ai کے}\n13۔ اور جب انہوں نے لوگوں کو، {حتیٰ کہ} شہر کے شمال میں موجود تمام لشکر اور ان کے جھوٹے شہر کے مغرب میں انتظار میں لگا دیے، تو یشوع اس رات وادی کے بیچ میں چلا گیا۔ {جھوٹے...: عبرانی۔ انتظار میں لگا ہوا}\n14۔ اور جب آئی کے بادشاہ نے دیکھا کہ وہ جلدی اٹھ کھڑے ہوئے، اور شہر کے لوگ اسرائیل کے خلاف جنگ کے لیے نکلے، وہ اور اس کے تمام لوگ، مقررہ وقت پر، میدان کے سامنے؛ لیکن وہ نہیں جانتا تھا کہ شہر کے پیچھے جھوٹے لوگ اس کے خلاف گھات میں ہیں۔ \n15۔ اور یشوع اور تمام اسرائیل نے ایسے ظاہر کیا جیسے وہ ان کے سامنے شکست کھا گئے ہوں، اور بیابان کے راستے سے بھاگ گئے۔ \n16۔ اور تمام لوگ جو عائی میں تھے، انہیں ان کے پیچھے پکڑنے کے لیے بلایا گیا، اور وہ یشوع کے پیچھے گئے، اور شہر سے دور ہو گئے۔ \n17۔ اور عائی یا بیت ال میں کوئی ایسا آدمی نہیں بچا جو اسرائیل کے پیچھے نہ جائے، بلکہ انہوں نے شہر کو کھلا چھوڑ دیا اور اسرائیل کے پیچھے دوڑا۔ \n18۔ اور خداوند نے یشوع سے کہا، اپنے ہاتھ میں موجود نیزہ عائی کی طرف بڑھاؤ؛ کیونکہ میں اسے تیرے ہاتھ میں دوں گا۔ اور یشوع نے وہ نیزہ جو اس کے ہاتھ میں تھا شہر کی طرف بڑھایا۔ \n19۔ اور کمین جلدی سے ان کی جگہ سے نکل آیا، اور جیسے ہی اس نے ہاتھ بڑھایا، وہ بھاگ گئے: اور وہ شہر میں داخل ہوئے، اسے لے لیے، اور جلدی سے شہر کو آگ لگا دی۔ \n20۔ اور جب عائی کے لوگوں نے پیچھے دیکھا، تو انہوں نے دیکھا، اور دیکھتے ہی شہر کا دھواں آسمان کی طرف چلا گیا، اور ان کے پاس اس طرف یا اس طرف بھاگنے کی طاقت نہیں تھی: اور جو لوگ بیابان میں بھاگے وہ پیچھا کرنے والوں کے خلاف پلٹ گئے۔ {طاقت: عبرانی۔ ہاتھ}\n21۔ اور جب یشوع اور تمام اسرائیل نے دیکھا کہ گھات نے شہر پر قبضہ کر لیا ہے، اور شہر کا دھواں اٹھ رہا ہے، تو وہ دوبارہ مڑے اور عائی کے لوگوں کو قتل کر دیا۔ \n22۔ اور دوسرا ان کے خلاف شہر سے نکل آیا؛ تو وہ اسرائیل کے بیچ میں تھے، کچھ اس طرف اور کچھ اس طرف: اور انہوں نے انہیں مارا، یہاں تک کہ ان میں سے کوئی بھی نہ رہ سکا اور نہ ہی بچ سکے۔ \n23۔ اور عائی کے بادشاہ کو زندہ پکڑ کر یشوع کے پاس لے آئے۔ \n24۔ اور ایسا ہوا، جب اسرائیل نے میدان میں، بیابان میں جہاں وہ ان کا پیچھا کر رہے تھے، اور جب وہ سب تلوار کے کنارے پر گر گئے، یہاں تک کہ وہ ختم ہو گئے، تو تمام بنی اسرائیل آ کے پاس واپس آئے اور تلوار کے نوک سے اسے مارا۔ \n25۔ اور {یوں} یہ تھا، {و} اس دن جو سب گرے، مرد اور عورتیں دونوں، {تھے} بارہ ہزار، {حتی} کہ آئی کے تمام مرد بھی۔ \n26۔ کیونکہ یشوع نے اپنا ہاتھ پیچھے نہیں کھینچا، جس سے اس نے نیزہ بڑھایا، یہاں تک کہ اس نے عائی کے تمام باشندوں کو مکمل طور پر تباہ کر دیا۔ \n27۔ صرف اس شہر کے مویشی اور مال غنیمت جنہیں اسرائیل نے اپنے لیے شکار بنایا، جیسا کہ خداوند نے یشوع کے حکم کے مطابق دیا۔ \n28۔ اور یشوع نے عائی کو جلا دیا، اور اسے ہمیشہ کے لیے ایک ڈھیر بنا دیا، {حتیٰ کہ} آج تک ویران رہا۔ \n29۔ اور عائی کے بادشاہ کو شام تک ایک درخت پر لٹکایا گیا: اور جیسے ہی سورج غروب ہوا، یشوع نے حکم دیا کہ اس کی لاش درخت سے اتار کر شہر کے دروازے کے دروازے پر پھینک دیں، اور اس پر پتھروں کا ایک بڑا ڈھیر کھڑا کریں، {جو آج تک باقی ہے}۔ \n30۔ پھر یشوع نے کوہ ایبال میں خداوند اسرائیل کے لیے قربان گاہ بنائی، \n31۔ جیسا کہ موسیٰ خداوند کے خادم نے بنی اسرائیل کو حکم دیا، جیسا کہ موسیٰ کی شریعت کی کتاب میں لکھا ہے، ایک مکمل پتھروں کا مذبح، جس پر کوئی لوہا نہیں اٹھا سکا: اور انہوں نے اس پر خداوند کے لیے سلائی قربانیاں پیش کیں، اور صلح کی قربانیاں قربان کیں۔ \n32۔ اور اس نے وہاں پتھروں پر موسیٰ کی شریعت کی ایک نقل لکھی، جو اس نے بنی اسرائیل کی موجودگی میں لکھی۔ \n33۔ اور تمام اسرائیل، ان کے بزرگ، افسران اور ان کے قاضی، صندوق کے اس طرف اور اس طرف لاوی کے سامنے کھڑے تھے، جو خداوند کے عہد کا صندوق اٹھائے ہوئے تھے، اور وہ اجنبی بھی، جو ان میں سے پیدا ہوا تھا؛ ان میں سے آدھے کوہ گریزیم کے خلاف تھے، اور آدھے کوہ ایبال کے خلاف؛ جیسا کہ موسیٰ خداوند کے خادم نے پہلے حکم دیا تھا کہ وہ اسرائیل کے لوگوں کو برکت دیں۔ \n34۔ اور اس کے بعد اس نے شریعت کے تمام الفاظ، برکتیں اور لعنتیں پڑھیں، جیسا کہ شریعت کی کتاب میں لکھا ہے۔ \n35۔ موسیٰ کے حکم میں سے ایک بھی لفظ نہیں تھا، جو یشوع نے اسرائیل کی تمام جماعت کے سامنے، عورتوں، چھوٹے بچوں اور ان اجنبیوں کے سامنے نہیں پڑھا جو ان میں سے بات کر رہے تھے۔ {تھے...: عبرانی۔ چلے}","1۔ اور یہ اس وقت ہوا جب وہ تمام بادشاہ جو اس طرف اردن، پہاڑوں میں، وادیوں میں، اور عظیم سمندر کے تمام ساحلوں پر لبنان، حتی، اموری، کنعانی، پریزی، حوی اور یبوسی کے خلاف تھے، نے اس کے بارے میں سنا؛ \n2۔ کہ وہ خود کو جمع کر کے یشوع اور اسرائیل کے ساتھ ایک اتحاد کے ساتھ لڑیں۔ {معاہدہ: عبرانی۔ منہ}\n3۔ اور جب گبعون کے باشندوں نے سنا کہ یشوع نے یریحو اور عائی کے ساتھ کیا کیا، \n4۔ انہوں نے چالاکی سے کام کیا، اور ایسے کام کیا جیسے وہ سفیر ہوں، اور پرانے بورے، شراب کی بوتلیں، پرانی اور کرایہ دار بوتلیں اور باندھنے لگے؛ \n5۔ اور ان کے پیروں پر پرانے جوتے اور کپڑے، اور ان پر پرانے کپڑے؛ اور ان کی ساری خوراک خشک اور پھپھوندی زدہ تھی۔ \n6۔ اور وہ یشوع کے پاس گلگل کے کیمپ میں گئے، اور اس سے اور اسرائیل کے لوگوں سے کہا، ہم دور دراز ملک سے آئے ہیں، اس لیے اب ہمارے ساتھ اتحاد کرو۔ \n7۔ اور اسرائیل کے لوگوں نے ہیویوں سے کہا، شاید تم ہمارے درمیان رہتے ہو؛ اور ہم تم سے اتحاد کیسے کریں؟ \n8۔ اور انہوں نے یشوع سے کہا، ہم تمہارے خادم ہیں۔ اور یشوع نے ان سے کہا، تم کون ہو؟ اور تم کہاں سے آئے ہو؟ \n9۔ اور انہوں نے اس سے کہا، تمہارے خادم بہت دور ملک سے آئے ہیں کیونکہ خداوند تیرے خدا کے نام کی وجہ سے آئے، کیونکہ ہم نے اس کی شہرت اور مصر میں اس کے کیے ہوئے سب کچھ سنا ہے، \n10۔ اور جو کچھ اس نے اموریوں کے دو بادشاہوں کے ساتھ کیا، جو اردن کے پار تھے، سیہون بادشاہ ہیشبون کے ساتھ، اور اوگ بادشاہ باشان کے ساتھ، جو اشتاروت میں تھا۔ \n11۔ اسی لیے ہمارے بزرگوں اور ہمارے ملک کے تمام باشندوں نے ہم سے کہا، سفر کے لیے اپنے ساتھ خوراک لے جاؤ، اور ان سے ملنے جاؤ، اور ان سے کہو، ہم تمہارے خادم ہیں، اس لیے اب ہمارے ساتھ اتحاد کرو۔ {تمہارے ساتھ: عبرانی۔ تمہارے ہاتھ میں}\n12۔ یہ ہماری روٹی تھی جو ہم نے اپنے گھروں سے گرم خوراک کے طور پر نکالی جب ہم تمہارے پاس جانے کے لیے نکلے؛ لیکن اب، دیکھو، یہ خشک اور پھپھوندی زدہ ہے: \n13۔ اور یہ شراب کی بوتلیں، جو ہم نے بھری تھیں، نئی تھیں؛ اور دیکھو، وہ پھٹ گئیں: اور یہ ہمارے کپڑے اور جوتے بہت طویل سفر کی وجہ سے پرانے ہو چکے ہیں۔ \n14۔ اور مردوں نے اپنی خوراک لے لی، اور خداوند کے منہ پر {مشورہ} نہیں مانگی۔ {مرد...: یا، انہوں نے اپنی خوراکوں کی وجہ سے لوگوں کو قبول کیا}\n15۔ اور یشوع نے ان سے صلح کر لی، اور ان سے اتحاد کیا کہ وہ زندہ رہیں: اور جماعت کے شہزادوں نے ان سے قسم کھائی۔ \n16۔ اور تین دن بعد جب انہوں نے ان سے اتحاد کیا، تو انہوں نے سنا کہ وہ ان کے پڑوسی ہیں، اور وہ ان کے درمیان رہتے ہیں۔ \n17۔ اور بنی اسرائیل روانہ ہوئے، اور تیسرے دن اپنے شہروں تک پہنچے۔ اب ان کے شہر گبعون، کفیرا، بیروت، اور کیرجاتجاریم تھے۔ \n18۔ اور بنی اسرائیل نے انہیں نہ مارا، کیونکہ جماعت کے شہزادوں نے ان سے خداوند خدا اسرائیل کی قسم کھائی تھی۔ اور تمام جماعت نے شہزادوں کے خلاف سرگوشیاں کیں۔ \n19۔ لیکن تمام شہزادوں نے تمام جماعت سے کہا، ہم نے ان سے اسرائیل کے خداوند خدا کی قسم کھائی ہے: اب ہم انہیں چھو نہیں سکتے۔ \n20۔ ہم ان کے ساتھ یہی کریں گے؛ ہم انہیں زندہ بھی چھوڑیں گے، کہیں ہم پر غصہ نہ آ جائے، اس قسم کی وجہ سے جو ہم نے ان سے کی ہے۔ \n21۔ اور شہزادوں نے ان سے کہا، انہیں زندہ رہنے دو؛ لیکن وہ لکڑی کاٹنے والے اور پانی کھینچنے والے بن جاؤ جو سب مجمع کے لیے تھے؛ جیسا کہ شہزادوں نے ان سے وعدہ کیا تھا۔ \n22۔ اور یشوع نے انہیں بلایا اور ان سے کہا، \"تم نے ہمیں کیوں بہکایا، کہہ رہے ہو، ہم تم سے بہت دور ہیں؛ جب تم ہمارے درمیان رہتے ہو؟ \n23. اب تم لعنت زدہ ہو، اور تم میں سے کوئی بھی میرے خدا کے گھر کے لیے غلام، لکڑی کاٹنے اور پانی نکالنے والے سے آزاد نہیں ہوگا۔ {کوئی نہیں...: عبرانی۔ تم سے کٹ نہیں جائے گا}\n24۔ اور انہوں نے یشوع کو جواب دیا اور کہا، \"کیونکہ تمہارے بندوں کو یقینا بتایا گیا تھا کہ خداوند تمہارا خدا اپنے بندے موسیٰ کو حکم دیتا ہے کہ وہ تمہیں ساری زمین دے دے، اور تمہارے سامنے سے زمین کے تمام باشندوں کو تباہ کر دے، اس لیے ہم تمہاری وجہ سے اپنی جانوں سے بہت ڈر گئے اور یہ کام کیا۔ \n25۔ اور اب، دیکھو، ہم تمہارے ہاتھ میں ہیں: جیسا کہ تمہیں اچھا اور درست لگتا ہے کہ ہمارے ساتھ کرو، کرو۔ \n26۔ اور اسی طرح اس نے ان کے ساتھ کام کیا، اور انہیں بنی اسرائیل کے ہاتھوں سے آزاد کرایا، کہ انہوں نے انہیں قتل نہ کیا۔ \n27۔ اور یشوع نے اس دن انہیں جماعت کے لیے لکڑی کاٹنے اور پانی نکالنے والے بنایا، اور آج تک خداوند کے قربان گاہ کے لیے، اس جگہ پر جہاں وہ منتخب کرتا۔ {بنایا: عبرانی۔ دیا، یا، دیا تاکہ ہو}","1۔ اب یہ ہوا جب یروشلم کے بادشاہ ادونیزیدیک نے سنا کہ یشوع نے عائی پر قبضہ کیا اور اسے مکمل طور پر تباہ کر دیا؛ جیسا کہ اس نے یریحو اور اس کے بادشاہ کے ساتھ کیا تھا، اسی طرح اس نے عائی اور اس کے بادشاہ کے ساتھ کیا تھا؛ اور کیسے گبعون کے باشندوں نے اسرائیل سے امن کر لیا تھا، اور وہ ان میں شامل تھے؛ \n2. کہ وہ بہت ڈرتے تھے، کیونکہ گبیعون ایک عظیم شہر تھا، شاہی شہروں میں سے ایک کے طور پر، اور کیونکہ وہ عائی سے بڑا تھا، اور اس کے تمام لوگ طاقتور تھے۔ {شاہی...: عبرانی۔ بادشاہت کے شہر}\n3۔ چنانچہ یروشلم کے بادشاہ ادونیزیک نے ہوحام بادشاہ ہیبرون، پیرام بادشاہ یارموت کو، یافیا کے بادشاہ لاخیش کو، اور ایگلون کے بادشاہ دبیر کو بھیجا، اور کہا، \n4۔ میرے پاس آؤ اور میری مدد کرو تاکہ ہم گبعون کو سزا دیں: کیونکہ اس نے یشوع اور بنی اسرائیل کے ساتھ صلح کر لی ہے۔ \n5۔ لہٰذا اموری کے پانچ بادشاہ، یروشلم کے بادشاہ، حبرون کے بادشاہ، یارموت کے بادشاہ، لاخیش کے بادشاہ، ایگلون کے بادشاہ، اکٹھے ہو کر اوپر چڑھے، وہ اور ان کے تمام لشکر گبعون کے سامنے خیمہ زن ہوئے اور اس کے خلاف جنگ کی۔ \n6۔ اور گبعون کے لوگوں نے یشوع کو گلگل کے کیمپ میں بھیجا، کہا، اپنے بندوں سے اپنا ہاتھ ڈھیلا نہ چھوڑو؛ جلدی ہمارے پاس آؤ، ہمیں بچا اور ہماری مدد کرو، کیونکہ پہاڑوں میں بسنے والے اموریوں کے تمام بادشاہ ہمارے خلاف جمع ہو گئے ہیں۔ \n7۔ یوں یشوع گلگل سے اوپر آیا، وہ، اور اس کے ساتھ تمام جنگ کے لوگ، اور تمام بہادر لوگ بھی۔ \n8۔ اور خداوند نے یشوع سے کہا، ان سے مت ڈرو، کیونکہ میں نے انہیں تیرے ہاتھ میں دے دیا ہے؛ ان میں سے کوئی بھی تیرے سامنے کھڑا نہیں ہو سکتا۔ \n9۔ یشوع اچانک ان کے پاس آیا، {اور} ساری رات گلگل سے اوپر چلا۔ \n10۔ اور خداوند نے انہیں اسرائیل کے سامنے پریشان کیا، اور گبعون میں بڑے قتل عام سے قتل کر دیا، اور ان کا پیچھا کیا جو بیت حورون تک جاتا ہے، اور انہیں عزیقہ اور مکیدہ تک مارا۔ \n11۔ اور جب وہ اسرائیل کے سامنے سے بھاگ رہے تھے، {اور} بیت ہورون کی طرف جا رہے تھے، تو خداوند نے ان پر آسمان سے عظیم پتھر اچھالے، اور وہ مر گئے: {وہ} وہ زیادہ تھے جو اولے کے ساتھ مرے، جتنے کہ وہ جنہیں بنی اسرائیل نے تلوار سے مارا۔ \n12۔ پھر یشوع نے خداوند سے اس دن کہا جب خداوند نے اموریوں کو بنی اسرائیل کے سامنے حوالے کیا، اور اس نے اسرائیل کی نظر میں کہا، سورج، جبعون پر کھڑے رہو؛ اور تو، چاند، اجلون کی وادی میں۔ {کھڑے ہو جاؤ...: عبرانی۔ خاموش رہو}\n13۔ اور سورج ساکت رہا، اور چاند رکا، جب تک کہ لوگوں نے اپنے دشمنوں سے انتقام نہ لیا۔ {کیا} یہ یاشر کی کتاب میں لکھا نہیں ہے؟ یوں سورج آسمان کے بیچ میں ساکت رہا، اور پورا دن غروب ہونے کی جلدی نہیں کی۔ {یاشر: یا، سیدھا؟}\n14۔ اور اس سے پہلے یا اس کے بعد ایسا کوئی دن نہیں تھا کہ خداوند نے کسی انسان کی آواز سنی: کیونکہ خداوند نے اسرائیل کے لیے لڑائی کی۔ \n15۔ اور یشوع اور تمام اسرائیل اس کے ساتھ گلگل کے کیمپ میں واپس آئے۔ \n16۔ لیکن یہ پانچ بادشاہ فرار ہو گئے اور مکیدہ کی ایک غار میں چھپ گئے۔ \n17۔ اور یشوع کو بتایا گیا کہ پانچ بادشاہ مکیدہ کی ایک غار میں چھپے ہوئے پائے گئے ہیں۔ \n18۔ اور یشوع نے کہا، غار کے منہ پر بڑے پتھر لڑھاؤ، اور لوگوں کو ان کی حفاظت کے لیے لگا دو: \n19۔ اور رکو مت، {بلکہ} اپنے دشمنوں کا پیچھا کرو، اور ان میں سے سب سے پیچھے والے کو مارو؛ انہیں اپنے شہروں میں داخل ہونے نہ دو، کیونکہ خداوند تمہارا خدا انہیں تمہارے ہاتھ میں دے چکا ہے۔ {مارو...: عبرانی۔ دم کاٹ دو}\n20۔ اور ایسا ہوا، جب یشوع اور بنی اسرائیل نے انہیں بہت بڑے قتل عام سے ختم کیا، یہاں تک کہ وہ ختم ہو گئے، تو باقی جو لوگ باقی تھے وہ باڑ والے شہروں میں داخل ہو گئے۔ \n21۔ اور سب لوگ سکون سے مکیدہ میں یشوع کے پاس واپس چلے گئے: کسی نے بنی اسرائیل کے خلاف زبان نہیں ہلائی۔ \n22۔ پھر یشوع نے کہا، غار کا منہ کھولو، اور ان پانچ بادشاہوں کو غار سے میرے پاس نکالو۔ \n23۔ اور انہوں نے ایسا کیا، اور ان پانچ بادشاہوں کو غار سے اس کے پاس لے آئے، یروشلم کا بادشاہ، ہیبرون کا بادشاہ، یارموت کا بادشاہ، لاخیش کا بادشاہ، {اور} ایگلون کا بادشاہ۔ \n24۔ اور جب وہ بادشاہوں کو یشوع کے پاس لے گئے، تو یشوع نے اسرائیل کے تمام آدمیوں کو بلایا اور اپنے ساتھ جانے والے جنگی سپاہیوں کے کپتانوں سے کہا، قریب آؤ، اپنے پاؤں ان بادشاہوں کی گردن پر رکھو۔ اور وہ قریب آئے، اور اپنے پاؤں ان کی گردن پر رکھ لیے۔ \n25۔ اور یشوع نے ان سے کہا، نہ ڈرو، نہ ڈرو، مضبوط اور حوصلہ رکھو، کیونکہ خداوند تمہارے تمام دشمنوں کے ساتھ ایسا ہی کرے گا جن کے خلاف تم لڑو گے۔ \n26۔ اور اس کے بعد یشوع نے انہیں مارا، قتل کیا، اور پانچ درختوں پر لٹکا دیا، اور وہ شام تک درختوں پر لٹکے رہے۔ \n27۔ اور سورج غروب ہوتے وقت یہ واقعہ ہوا، {وہ} یشوع نے حکم دیا، اور انہوں نے انہیں درختوں سے اتار کر غار میں پھینک دیا جہاں وہ چھپے ہوئے تھے، اور غار کے منہ میں بڑے پتھر رکھے، {جو آج تک باقی ہیں}۔ \n28۔ اور اس دن یشوع نے مکیدہ پر قبضہ کیا، اور تلوار کی نوک سے اسے مارا، اور اس کے بادشاہ کو مکمل طور پر تباہ کر دیا، اور اس میں موجود تمام جانیں بھی؛ اس نے کسی کو باقی نہ چھوڑا: اور اس نے مکیدہ کے بادشاہ کے ساتھ وہی کیا جو اس نے یریحو کے بادشاہ کے ساتھ کیا۔ \n29۔ پھر یشوع مکیدہ سے اور اس کے ساتھ تمام اسرائیل سے گزر کر لبنہ پہنچا اور لبنہ کے خلاف لڑا: \n30۔ اور خداوند نے اسے اور اس کے بادشاہ کو بھی اسرائیل کے ہاتھ میں دے دیا؛ اور اس نے تلوار کی نوک سے اسے مارا، اور اس میں موجود تمام روحوں کو؛ اس نے کسی کو اس میں رہنے دیا؛ بلکہ اس کے بادشاہ کے ساتھ وہی کیا جو اس نے یریحو کے بادشاہ کے ساتھ کیا۔ \n31۔ اور یشوع لبنہ اور اس کے ساتھ تمام اسرائیل سے لاخیش پہنچا، اس کے خلاف خیمہ لگایا، اور اس کے خلاف لڑا: \n32۔ اور خداوند نے لاخیش کو اسرائیل کے ہاتھ میں دیا، جس نے دوسرے دن اسے لے لیا، اور تلوار کی نوک سے مارا، اور اس میں موجود تمام روحوں کو جو اس نے لبنہ کے ساتھ کیے تھے، اس کے مطابق مارا۔ \n33۔ پھر ہورام، گزر کا بادشاہ، لاخیش کی مدد کے لیے آیا؛ اور یشوع نے اسے اور اس کے لوگوں کو مارا، یہاں تک کہ اس کے پاس کوئی باقی نہ رہا۔ \n34۔ اور لاخیش سے یشوع ایگلون اور اس کے ساتھ تمام اسرائیل کے پاس گیا؛ اور انہوں نے اس کے خلاف خیمہ باز کیا اور اس کے خلاف لڑا: \n35۔ اور اس دن انہوں نے اسے لے لیا، تلوار کے نوک سے مارا، اور اس میں موجود تمام جانوں کو اس دن مکمل طور پر تباہ کر دیا، جیسا کہ اس نے لاخیش کے ساتھ کیا تھا۔ \n36۔ اور یشوع ایگلون اور تمام اسرائیل اس کے ساتھ ہیبرون چلے گئے؛ اور انہوں نے اس کے خلاف جنگ کی: \n37۔ اور انہوں نے اسے لے لیا، اور تلوار کی نوک سے مارا، اور اس کے بادشاہ، اس کے تمام شہروں کو، اور وہاں موجود تمام روحوں کو؛ اس نے ایگلون کے ساتھ جو کچھ کیا تھا اس کے مطابق کوئی باقی نہ رہا؛ بلکہ اسے مکمل طور پر تباہ کر دیا، اور اس میں موجود تمام روحیں بھی۔ \n38۔ اور یشوع اور تمام اسرائیل اس کے ساتھ دبیر واپس آئے؛ اور اس کے خلاف لڑا: \n39۔ اور اس نے اسے لے لیا، اس کے بادشاہ کو، اور اس کے تمام شہروں کو؛ اور انہوں نے تلوار کی نوک سے انہیں مارا، اور وہاں موجود تمام روحوں کو مکمل طور پر تباہ کر دیا؛ اس نے کوئی باقی نہ چھوڑا: جیسے اس نے ہیبرون کے ساتھ کیا تھا، ویسے ہی اس نے دبیر اور اس کے بادشاہ کے ساتھ کیا؛ جیسا کہ اس نے لبنہ اور اس کے بادشاہ کے ساتھ بھی کیا تھا۔ \n40۔ یوں یشوع نے پہاڑوں، جنوب، وادیوں، چشموں اور ان کے تمام بادشاہوں کو تباہ کر دیا: اس نے کوئی باقی نہ چھوڑا، بلکہ جو کچھ سانس لیتا تھا اسے مکمل طور پر تباہ کر دیا، جیسا کہ خداوند خدا اسرائیل نے حکم دیا تھا۔ \n41۔ اور یشوع نے انہیں کادیشبرنیا سے غزہ تک، اور پورے گوشن کے علاقے تک، حتیٰ کہ گبعون تک مار ڈالا۔ \n42۔ اور یہ تمام بادشاہ اور ان کی زمین یشوع نے ایک وقت میں حاصل کی، کیونکہ اسرائیل کے خداوند خدا نے اسرائیل کے لیے لڑائی کی۔ \n43۔ اور یشوع اور تمام اسرائیل اس کے ساتھ گلگل کے کیمپ میں واپس آئے۔","1۔ اور ایسا ہوا، جب ہازور کے بادشاہ یابین نے {یہ باتیں} سنیں، کہ اس نے مدون کے بادشاہ جوباب، شمرون کے بادشاہ، اور اخشاف کے بادشاہ کو بھیجا، \n2۔ اور ان بادشاہوں کے لیے جو پہاڑوں کے شمال میں، چینروتھ کے جنوب میں میدانوں میں، وادی میں، اور مغرب میں دور کی سرحدوں پر تھے، \n3۔ اور مشرق اور مغرب میں کنعانیوں کو، اور اموری، حتی، اور پرزی، اور پہاڑوں میں یبوسی کو، اور حوی کو جو ہرمون کے تحت مزپیہ کی سرزمین میں ہے۔ \n4۔ اور وہ باہر نکلے، وہ اور ان کے تمام لشکر بھی ساتھ تھے، بہت سے لوگ، جیسے سمندر کے کنارے ریت کی طرح، گھوڑے اور رتھ بہت سے تھے۔ \n5۔ اور جب یہ سب بادشاہ اکٹھے ہوئے، تو وہ میرم کے پانیوں پر اکٹھے ہو کر اسرائیل سے لڑنے لگے۔ {ملاقات...: عبرانی۔ مقررہ وقت پر جمع ہوئے}\n6۔ اور خداوند نے یشوع سے کہا، ان کی وجہ سے نہ ڈرو، کیونکہ کل اسی وقت میں ان سب کو اسرائیل کے سامنے مارے گئے سب کو بچا دوں گا: تو ان کے گھوڑے سوار کرو گے اور ان کی رتھیں آگ سے جلا دو۔ \n7۔ تو یشوع اور اس کے ساتھ تمام جنگی لوگ اچانک میرم کے پانیوں کے پاس ان کے خلاف آئے؛ اور وہ ان پر حملہ آور ہو گئے۔ \n8۔ اور خداوند نے انہیں اسرائیل کے ہاتھ میں دے دیا، جس نے انہیں مارا، اور انہیں عظیم زیدون، مسریفوتھمائیم، اور مشرق کی طرف میزپے وادی تک پیچھا کیا؛ اور انہوں نے انہیں مارا، یہاں تک کہ ان کے پاس کوئی باقی نہ رہا۔ {عظیم زیدون: یا، زیدونرابا} {میسریفوتھمائم: یا، نمک کے گڑھے: عبرانی۔ پانیوں کی جلنا}\n9۔ اور یشوع نے ان کے ساتھ ویسا ہی کیا جیسا خداوند نے حکم دیا: اس نے ان کے گھوڑے لگا دیے، اور ان کے رتھوں کو آگ سے جلا دیا۔ \n10۔ اور یشوع اس وقت پلٹا، حزور کو لے کر اس کے بادشاہ کو تلوار سے مارا: کیونکہ حزور پہلے ان تمام سلطنتوں کا سربراہ تھا۔ \n11۔ اور انہوں نے ان تمام روحوں کو جو وہاں تھیں، تلوار کے دھار سے مارا، انہیں مکمل طور پر تباہ کر دیا: سانس لینے کے لیے کوئی باقی نہ رہا: اور اس نے حازور کو آگ سے جلا دیا۔ {کوئی...: عبرانی۔ کوئی سانس}\n12۔ اور ان بادشاہوں کے تمام شہر اور ان کے تمام بادشاہوں نے یشوع نے قبضے میں لے کر تلوار کی نوک سے مارا، {اور} انہیں مکمل طور پر تباہ کر دیا، جیسا کہ موسیٰ خداوند کے خادم نے حکم دیا تھا۔ \n13. لیکن {جہاں تک} ان شہروں کا تعلق ہے جو اپنی طاقت میں کھڑے رہے، اسرائیل نے ان میں سے کوئی نہیں جلایا، سوائے حزور کے؛ {یہ} یشوع نے جلا دیا۔ {ان کے...: عبرانی۔ ان کے ڈھیر پر}\n14۔ اور ان شہروں کی ساری لوٹ مار اور مویشیوں کو بنی اسرائیل نے اپنے لیے شکار بنا لیا؛ لیکن ہر آدمی کو تلوار کی نوک سے مارا، یہاں تک کہ انہیں تباہ کر دیا، کسی کو سانس لینے کے لیے نہ چھوڑا۔ \n15۔ جیسے خداوند نے موسیٰ کو اپنے خادم کا حکم دیا، ویسے ہی موسیٰ نے یشوع کو حکم دیا، اور یشوع نے بھی؛ اس نے وہ سب کچھ نہیں چھوڑا جو خداوند نے موسیٰ کو حکم دیا تھا۔ {چھوڑ دیا...: عبرانی۔ کچھ نہیں ہٹایا}\n16۔ تو یشوع نے وہ ساری زمین، پہاڑیاں، سارا جنوبی علاقہ، اور گوشن کی ساری زمین، وادی، میدان، اسرائیل کا پہاڑ اور اسی وادی پر قبضہ کر لیا؛ \n17۔ {حتیٰ کہ} پہاڑ ہلاک سے، جو سعیر تک جاتا ہے، حتیٰ کہ لبنان کی وادی میں واقع بعلگاد تک، جو کوہ ہرمون کے نیچے ہے: اور ان کے تمام بادشاہوں کو اس نے پکڑا، انہیں مارا اور قتل کر دیا۔ {پہاڑ...: یا، ہموار پہاڑ}\n18۔ یشوع نے ان تمام بادشاہوں کے ساتھ طویل عرصے تک جنگ کی۔ \n19۔ کوئی بھی شہر بنی اسرائیل سے امن قائم نہیں کرتا تھا، سوائے ہیویوں کے جو گبعون کے باشندے تھے: باقی سب کو انہوں نے جنگ میں لیا۔ \n20۔ کیونکہ یہ خداوند کی طرف سے تھا کہ وہ ان کے دل سخت کرے، کہ وہ جنگ میں اسرائیل کے خلاف آئیں، تاکہ وہ انہیں مکمل طور پر تباہ کر دے، {اور} کہ انہیں کوئی فضل نہ ملے، لیکن وہ انہیں تباہ کر دے، جیسا کہ خداوند نے موسیٰ کو حکم دیا تھا۔ \n21۔ اور اسی وقت یشوع آیا، اور اس نے اناقیم کو پہاڑوں سے، حبرون، دبیر، عناب، یہوداہ کے تمام پہاڑوں اور اسرائیل کے تمام پہاڑوں سے کاٹ دیا: یشوع نے انہیں ان کے شہروں کے ساتھ مکمل طور پر تباہ کر دیا۔ \n22۔ بنی اسرائیل کی سرزمین میں اناقیم میں سے کوئی باقی نہیں تھا: صرف غزہ، گت اور اشدود میں باقی رہ گئے تھے۔ \n23۔ تو یشوع نے ساری زمین لے لی، جیسا کہ خداوند نے موسیٰ سے کہا تھا؛ اور یشوع نے یہ زمین اسرائیل کو ان کی قبائل کی تقسیم کے مطابق وراثت میں دے دی۔ اور زمین جنگ سے بچ گئی۔","1۔ اب یہ {ہیں} اس سرزمین کے بادشاہ، جنہیں بنی اسرائیل نے تباہ کیا، اور انہوں نے سورج کے طلوع آفتاب کے قریب، دریائے ارنون سے لے کر کوہ حرمون تک، اور مشرق کے تمام میدان میں اپنی زمین پر قبضہ کر لیا: \n2۔ سیہون، اموریوں کا بادشاہ، جو ہشبون میں رہتا تھا، {اور} آروئر سے حکمرانی کرتا تھا، جو دریائے ارنون کے کنارے {ہے}، اور دریا کے وسط سے، اور آدھے گلعاد سے یہاں تک کہ دریائے جبک تک، {جو آمون کے بچوں کی سرحد ہے}؛ \n3۔ اور میدان سے مشرق میں چنیروتھ کے سمندر تک، اور میدانی سمندر تک، {حتیٰ کہ} مشرق میں نمکین سمندر تک، بیت جیشیموت کی طرف؛ اور جنوب سے، اشدوتھپسگاہ کے نیچے: {جنوب: یا، تیمان} {اشدوتھپیسگاہ: یا، پسگاہ کے چشمے، یا پہاڑ}\n4۔ اور اوگ بادشاہ باشان کا ساحل، جو دیوؤں کے باقیات میں سے تھا، جو اشتاروت اور ایڈری میں رہتے تھے، \n5۔ اور کوہ حرمون میں، سلکہ میں، اور پورے باشان میں، گشوریوں اور ماخاتیوں کی سرحد تک، اور آدھی جلعاد، جو ہیشبون کے بادشاہ سیہون کی سرحد ہے، پر حکومت کی۔ \n6۔ انہیں موسیٰ، جو خداوند کا خادم اور بنی اسرائیل تھا، نے مارا: اور موسیٰ خداوند کے خادم نے اسے روبینوں، گادیوں اور منسی کے آدھے قبیلے کو ایک ملکیت دی۔ \n7۔ اور یہ وہ بادشاہ ہیں جنہیں یشوع اور بنی اسرائیل نے اس طرف مغرب، لبنان کی وادی میں بعلگاد سے لے کر کوہ ہلاک تک، جو سعیر تک جاتا ہے، کو شکست دی؛ جو یشوع نے اسرائیل کے قبائل کو ان کی تقسیم کے مطابق ملکیت دی؛ \n8۔ پہاڑوں میں، وادیوں میں، میدانوں میں، چشموں میں، بیابانوں میں، اور جنوبی علاقوں میں؛ حتی، اموری، کنعانی، پریزی، حوی اور یبوسی میں: \n9۔ یریحو کا بادشاہ، ایک؛ عائی کا بادشاہ، جو بیت ال کے ساتھ ہے، ایک؛ \n10۔ یروشلم کا بادشاہ، ایک؛ حبرون کا بادشاہ، ایک؛ \n11۔ جارموت کا بادشاہ، ایک؛ لاچیش کا بادشاہ، ایک؛ \n12۔ ایگلون کا بادشاہ، ایک؛ گیزر کا بادشاہ، ایک؛ \n13۔ دیبیر کا بادشاہ، ایک؛ گدر کا بادشاہ، ایک؛ \n14۔ ہورماہ کا بادشاہ، ایک؛ اراد کا بادشاہ، ایک؛ \n15۔ لبنہ کا بادشاہ، ایک؛ ادلم کا بادشاہ، ایک؛ \n16۔ مکیدہ کا بادشاہ، ایک؛ بیت ال کا بادشاہ، ایک؛ \n17۔ ٹپواہ کا بادشاہ، ایک؛ ہیفر کا بادشاہ، ایک؛ \n18۔ ایفیک کا بادشاہ، ایک؛ لاشارون کا بادشاہ، ایک؛ {لاشارون: یا، شارون}\n19۔ مدون کا بادشاہ، ایک؛ ہازور کا بادشاہ، ایک؛ \n20۔ شمرونمیرون کا بادشاہ، ایک؛ اکشاف کا بادشاہ؛ \n21۔ تانخ کا بادشاہ، ایک؛ میگیدو کا بادشاہ، ایک؛ \n22۔ قدیش کا بادشاہ، ایک؛ کرمل کا یوکنام کا بادشاہ، ایک؛ \n23۔ دور کے ساحل پر دور کا بادشاہ، ایک؛ گلگل کی قوموں کا بادشاہ، ایک؛ \n24۔ تیرزہ کا بادشاہ، ایک: تمام بادشاہ تیس اور ایک۔","1۔ اب یشوع بوڑھا ہو گیا تھا {اور} عمر میں مبتلا ہو چکا تھا؛ اور خداوند نے اسے فرمایا، تو بوڑھا ہو {اور} سالوں میں زخمی ہو چکا ہے، اور ابھی بھی بہت سی زمین باقی ہے جسے حاصل کیا جا سکے۔ {کو...: عبرانی۔ اسے حاصل کرنے کے لیے}\n2. یہ وہ زمین ہے جو ابھی باقی ہے: فلسطینیوں کی تمام سرحدیں، اور تمام گشوری، \n3۔ سیہور سے، جو مصر سے پہلے ہے، حتیٰ کہ ایکرون کی سرحدوں تک شمال میں، {جو} کنعانیوں میں شمار ہوتا ہے: فلسطینیوں کے پانچ سردار؛ غزاثی، اور اشدوتائی، اشکالون، گتائی، اور ایکرونی؛ اور آویت بھی: \n4۔ جنوب سے، کنعانیوں کی ساری زمین، اور میعرا جو صیدونیوں کے ساتھ ہے، افیق، اموری کی سرحدوں تک: {میارا: یا، غار}\n5۔ اور گبلیٹس کی زمین، اور پورے لبنان، سورج نکلنے کی طرف، بعلگاد سے لے کر کوہ حرمون کے نیچے حمات کے داخلے تک۔ \n6۔ لبنان سے لے کر مسریفوتھمائیم تک پہاڑی علاقے کے تمام باشندے، {اور} تمام صیدونیوں کو، میں انہیں بنی اسرائیل کے سامنے نکالوں گا: صرف اسے قرعہ اندازی کر کے بنی اسرائیل کو وراثت کے طور پر تقسیم کرو، جیسا کہ میں نے تمہیں حکم دیا ہے۔ \n7۔ اب اس زمین کو نو قبائل اور مناسی کے آدھے قبیلے کو وراثت کے لیے تقسیم کرو، \n8۔ جن کے ساتھ روبینیوں اور گدائیوں نے اپنی وراثت حاصل کی، جو موسیٰ نے انہیں اردن کے پار مشرق کی طرف دی تھی، {حتیٰ کہ} جیسا کہ موسیٰ خداوند کے خادم نے انہیں دیا؛ \n9۔ آروئر سے، جو دریائے ارنون کے کنارے ہے، اور اس شہر سے جو دریا کے بیچ میں ہے، اور میڈیبا کے تمام میدان سے دیبون تک؛ \n10۔ اور اموری کے بادشاہ سیحون کے تمام شہر، جو ہشبون میں حکمرانی کرتے تھے، آمون کے بچوں کی سرحد تک؛ \n11۔ اور گلعاد، اور گشوریوں اور ماخاتیوں کی سرحد، اور سب کوہ ہیرمون، اور تمام باشان سلکہ تک؛ \n12۔ اوگ کی تمام بادشاہت باشان میں، جو اشتاروت اور ادری میں حکمرانی کرتی تھی، جو دیوؤں کے باقیات میں سے باقی رہ گئی: کیونکہ موسیٰ نے انہیں مارا اور نکال دیا۔ \n13۔ تاہم بنی اسرائیل نے نہ تو گشوریوں کو نکالا، نہ ہی ماخاتیوں کو، بلکہ گیشوری اور ماخاتیوں آج تک بنی اسرائیل میں رہتے ہیں۔ \n14۔ صرف لیوی قبیلے کو اس نے کوئی وراثت نہیں دی؛ خداوند خدا اسرائیل کی آگ سے دی گئی قربانیاں ان کی وراثت ہیں، جیسا کہ اس نے انہیں کہا۔ \n15۔ اور موسیٰ نے روبن کے قبیلے کو ان کے خاندانوں کے مطابق {وراثت} دی۔ \n16۔ اور ان کا ساحل آروئر سے تھا، جو دریائے ارنون کے کنارے واقع ہے، اور وہ شہر جو دریا کے بیچ میں ہے، اور میدیبہ کے کنارے پورا میدان؛ \n17۔ ہشبون، اور اس کے تمام شہر جو میدان میں ہیں؛ دیبون، اور باموثبال، اور بیت باعلمیون، {باموثبال...: یا، بعل کے بلند مقامات، اور بعلمیون کا گھر}\n18. اور جہازہ، اور کیدیموت، اور میفاتھ، \n19۔ اور کرجاتھیم، اور سبمہ، اور زارتھ شہر وادی کے پہاڑ پر، \n20۔ اور بیت پیور، اور اشدوتھپیسگا، اور بیت جیشیموت، {اشدوتھپیسگاہ: یا، پسگاہ کے چشمے، یا، پہاڑ}\n21۔ اور میدان کے تمام شہر، اور اموری کے بادشاہ سیہون کی تمام بادشاہت، جو ہیشبون میں حکمرانی کرتی تھی، جنہیں موسیٰ نے مدیان، ایوی، ریکیم، زور، اور ہور، اور ربا کے شہزادوں کے ساتھ مارا تھا، جو سیہون کے ڈیوک تھے اور اس دیہات میں بستے تھے۔ \n22۔ بعلم، جو بیور کا بیٹا بھی تھا، نے ان میں سے جو ان کے ہاتھوں مارے گئے تھے، بنی اسرائیل نے تلوار سے قتل کر دیا۔ {فال: یا، غیب گو}\n23۔ اور روبن کے بچوں کی سرحد اردن اور اس کی سرحد تھی۔ یہ روبن کے بچوں کی ان کے خاندانوں، شہروں اور دیہات کے بعد وراثت تھی۔ \n24۔ اور موسیٰ نے جاد کے قبیلے کو {وراثت} دی، {حتیٰ کہ} گاد کے بچوں کو ان کے خاندانوں کے مطابق بھی۔ \n25۔ اور ان کا ساحل یازر تھا، اور گیلعاد کے تمام شہر، اور آمون کے بچوں کی آدھی زمین، جو رباح کے سامنے ہے، آروئر تک؛ \n26۔ اور ہیشبون سے رامتھمیزپہ اور بیتونیم تک؛ اور مہانائم سے دیبیر کی سرحد تک؛ \n27۔ اور وادی میں، بیتھارام، بیت نیمرا، اور سوکوتھ، اور زافون، سیہون بادشاہ ہشبون، اردن کی باقی سلطنت اور اس کی سرحد، حتیٰ کہ اردن کے دوسری طرف چنیرتھ کے سمندر کے کنارے تک۔ \n28. یہ جاد کے بچوں کی وراثت ہے ان کے خاندانوں، شہروں اور دیہات کے بعد۔ \n29۔ اور موسیٰ نے منسی کے آدھے قبیلے کو {وراثت} دی: اور {یہ} منسی کے بچوں کے آدھے قبیلے کے خاندانوں کی ملکیت تھی۔ \n30۔ اور ان کا ساحل مہنایم سے تھا، تمام باشان، اوگ بادشاہ بشان کی تمام سلطنت، اور جائر کے تمام قصبے، جو باشان میں ہیں، تین سو شہر: \n31۔ اور آدھے گیلعاد، اشتاروت، اور ادری، اوگ کی سلطنت کے شہر باشان میں، مخر کے بیٹے منسی کے بچوں سے تعلق رکھتے تھے، {حتیٰ کہ} ماخیر کے آدھے بچوں کے خاندانوں سے بھی۔ \n32. یہ وہ ممالک ہیں جنہیں موسیٰ نے موآب کے میدانوں میں، اردن کے دوسری طرف، مشرق کی طرف اردن کے کنارے وراثت کے لیے تقسیم کیا۔ \n33۔ لیکن لیوی قبیلے کو موسیٰ نے کوئی وراثت نہیں دی: خداوند خدا اسرائیل ان کی وراثت تھا، جیسا کہ اس نے انہیں کہا۔","1۔ اور یہ وہ ممالمیں ہیں جو بنی اسرائیل نے کنعان کی سرزمین میں وراثت میں حاصل کیں، جو الیعزر کاهن اور یشوع نون کے بیٹے، اور بنی اسرائیل کے قبائل کے باپوں کے سروں نے انہیں وراثت کے لیے تقسیم کیا۔ \n2. قرعہ کے ذریعے ان کی وراثت {تھی}، جیسا کہ خداوند نے موسیٰ کے ہاتھ سے حکم دیا، نو قبائل کے لیے، اور {آدھے قبیلے} کے لیے۔ \n3۔ کیونکہ موسیٰ نے اردن کے دوسری طرف دو قبیلوں اور آدھے قبیلے کی وراثت دی تھی، لیکن لاویوں کو ان میں سے کوئی وراثت نہیں دی۔ \n4۔ یوسف کی اولاد دو قبیلے تھے، منسی اور افرائیم: اس لیے انہوں نے زمین میں لاویوں کو کوئی حصہ نہیں دیا، سوائے شہروں کے، جن کے مضافات میں ان کے مویشی اور مال تھے۔ \n5۔ جیسا کہ خداوند نے موسیٰ کو حکم دیا، ویسے ہی بنی اسرائیل نے بھی کیا، اور انہوں نے زمین تقسیم کی۔ \n6۔ پھر یہوداہ کے بچے گلگل میں یشوع کے پاس آئے: اور کالب، یپھونہ کنیزی کے بیٹے نے اسے کہا، تم جانتے ہو کہ خداوند نے خدا کے آدمی موسیٰ سے میرے اور تمہارے بارے میں کادیشبرنیا میں کیا کہا۔ \n7۔ چالیس سال کا تھا جب موسیٰ، خداوند کا بندہ مجھے کدیشبرنیا سے بھیجا کہ میں زمین کی جاسوسی کروں؛ اور میں نے اسے دوبارہ پیغام دیا جیسا کہ میرے دل میں تھا۔ \n8۔ پھر بھی میرے بھائیوں نے جو میرے ساتھ گئے، لوگوں کے دل پگھلا دیے: لیکن میں نے مکمل طور پر خداوند میرے خدا کی پیروی کی۔ \n9۔ اور موسیٰ اس دن قسم کھاتا ہے، کہتا ہے، یقینا وہ زمین جس پر تمہارے قدم چلے، وہ ہمیشہ تمہاری میراث اور تمہارے بچوں کی ہوگی، کیونکہ تم نے میرے خدا کے خدا کی مکمل پیروی کی ہے۔ \n10۔ اور اب، دیکھو، خداوند نے مجھے زندہ رکھا ہے، جیسا کہ اس نے کہا، یہ پینتالیس سال سے، جب سے خداوند نے یہ کلام موسیٰ سے کہا، جب {بنی اسرائیل} بیابان میں بھٹکتے رہے: اور اب، دیکھو، میں آج چالیس اور پانچ سال کا ہوں۔ {گھومتا رہا: عبرانی۔ چلتا رہا}\n11. آج بھی میں اتنی ہی مضبوط ہوں جتنی میں اس دن تھی جب موسیٰ نے مجھے بھیجا: جیسے میری طاقت تب تھی، ویسی ہی اب میری طاقت ہے، جنگ کے لیے، باہر جانے اور اندر آنے کے لیے۔ \n12۔ اب مجھے یہ پہاڑ دو، جس کے بارے میں خداوند نے اس دن بات کی تھی؛ کیونکہ تم نے اس دن سنا کہ اناقیم وہاں تھے، اور شہر بڑے اور باڑ والے تھے: اگر ایسا ہو تو خداوند میرے ساتھ ہو تو میں انہیں نکال سکوں گا، جیسا کہ خداوند نے فرمایا۔ \n13۔ اور یشوع نے اسے برکت دی، اور کیلب کے بیٹے یپھونہ ہبرون کو وراثت کے طور پر دیا۔ \n14۔ یوں ہیبرون نے آج تک کیلب کی وراثت حاصل کی، جو یپھونہ کنزی کا بیٹا تھا، کیونکہ وہ مکمل طور پر اسرائیل کے خداوند خدا کی پیروی کرتا تھا۔ \n15۔ اور ہیبرون کا نام {تھا} کرجاتھاربا سے پہلے؛ {جس میں اربا تھا} اناکیمز میں ایک عظیم آدمی تھا۔ اور زمین کو جنگ سے آرام ملا۔","1. {یہ} یہوداہ کے بچوں کے قبیلے کی قسمت تھی جو ان کے خاندانوں کے لحاظ سے تھی؛ {حتیٰ کہ} ایڈوم کی سرحد تک، جنوب کی طرف زین کا بیابان {تھا} جنوبی ساحل کا سب سے بڑا حصہ۔ \n2۔ اور ان کی جنوبی سرحد نمکین سمندر کے کنارے سے تھی، اس خلیج سے جو جنوب کی طرف دیکھتی ہے: {خلیج: عبرانی۔ زبان}\n3۔ اور یہ جنوب کی طرف ماعلحاکربم تک گیا، پھر زین تک گیا، پھر جنوب کی طرف چڑھ کر قدیشبرنیا پہنچا، پھر حزرون تک گیا، پھر آدار تک گیا، اور کرعہ کے لیے کمپاس لایا تھا: {معلیحاکریبیم: یا، اکرابیم کی طرف جانا}\n4. {وہاں سے} وہ عزمون کی طرف گیا، اور مصر کے دریا تک گیا؛ اور اس ساحل سے نکلنے والے راستے سمندر کے کنارے تھے: یہ تمہارا جنوبی ساحل ہوگا۔ \n5۔ اور مشرقی سرحد {تھی} نمکین سمندر تھی، {حتی} اردن کے آخر تک۔ اور {ان کی} سرحد شمالی حصے میں {تھی} سمندر کی خلیج سے جو اردن کے انتہائی حصے میں ہے: \n6۔ اور سرحد بیت ہوغلا تک جاتی تھی، اور بیتھربہ کے شمال سے گزرتی تھی؛ اور سرحد بوہان کے پتھر تک جاتی تھی، جو روبن کا بیٹا تھا: \n7۔ اور سرحد آخور کی وادی سے دیبیر کی طرف جاتی تھی، اور پھر شمال کی طرف، گلگل کی طرف دیکھتے ہوئے، یعنی ادومیم کی طرف جانے سے پہلے، جو دریا کے جنوبی کنارے پر ہے، اور سرحد انشمیش کے پانیوں کی طرف جاتی تھی، اور وہاں سے نکلنے کا راستہ اینروگل پر تھا: \n8۔ اور سرحد حنوم کے بیٹے کی وادی کے پاس یبوسی کے جنوب کی طرف جاتی تھی؛ وہی {ہے} یروشلم: اور سرحد اس پہاڑ کی چوٹی تک جاتی تھی جو {یتھ} ہنوم کی وادی سے پہلے مغرب کی طرف ہے، جو {ہے} دیوؤں کی وادی کے آخر میں: \n9۔ اور سرحد پہاڑی کی چوٹی سے نیفتوا کے پانی کے چشمے تک کھینچی گئی، اور ایفرون پہاڑ کے شہروں تک جاتی تھی؛ اور سرحد بعلہ تک کھینچی گئی، جو {ہے} کرجاتجاریم ہے: \n10۔ اور سرحد بعلہ سے مغرب کی طرف کوہ سعیر تک جاتی تھی، اور شمال میں کوہ یریم کے کنارے تک جاتی تھی، جو کہ چسلون ہے، اور بیت شمش تک جاتی تھی، اور پھر تیمنا تک جاتی تھی: \n11۔ اور سرحد ایکرون کے کنارے شمال کی طرف نکل گئی: اور سرحد شکرون کی طرف کھینچی گئی، پھر کوہ بعلہ تک جاتی اور پھر جبنیل تک جاتی رہی؛ اور سرحد سے نکلنے والے راستے سمندر کے کنارے تھے۔ \n12۔ اور مغربی سرحد عظیم سمندر اور اس کے ساحل سے تھی۔ یہ یہوداہ کے بچوں کا ساحل ہے جو ان کے خاندانوں کے مطابق ہے۔ \n13۔ اور کالب، یپھونہ کے بیٹے کو اس نے یہوداہ کی اولاد میں سے ایک حصہ خداوند کے حکم کے مطابق یشوع کو دیا، {حتیٰ کہ} شہر اربا جو عناک کا باپ ہے، جو {شہر} ہے ہیبرون۔ {شہر...: یا، کرجاتھربا}\n14۔ اور کالب نے وہاں سے انک کے تین بیٹے، شیشائی اور اہیم، اور تلمائی، جو انک کے بچے تھے، وہاں سے نکالا۔ \n15۔ اور وہ وہاں سے دیبیر کے باشندوں کے پاس چلا گیا: اور دیبیر کا نام {تھا} کرجاتھسیفر سے پہلے تھا۔ \n16۔ اور کیلب نے کہا، جو کرجاتسیفر کو مارے گا، اور اسے لے جائے گا، میں اپنی بیٹی کو اس کے حوالے کروں گا۔ \n17۔ اور اوثنیئل، کیناز کا بیٹا، جو کالب کا بھائی تھا، نے اسے لے لیا: اور اس نے اپنی بیٹی اکسا کو بیوی کے طور پر دے دیا۔ \n18۔ اور جب وہ اس کے پاس آئی، تو اس نے اسے اپنے والد سے کھیت مانگنے کو کہا: اور اس نے اپنا گدھا جلا دیا؛ اور کیلب نے اس سے کہا، تم کیا چاہتی ہو؟ \n19۔ جس نے جواب دیا، مجھے برکت دو؛ کیونکہ تم نے مجھے جنوبی زمین دی ہے؛ مجھے پانی کے چشمے بھی دے۔ اور اس نے اسے اوپر والے چشمے اور نیچے کے چشمے دیے۔ \n20. یہ یہوداہ کے بچوں کے قبیلے کی خاندانوں کے مطابق وراثت ہے۔ \n21۔ اور یہوداہ کے قبیلے کے سب سے دور کے شہر جو ایڈوم کے ساحل کی طرف جنوب کی طرف تھے، کبزئیل، ایدر اور یغور تھے، \n22۔ اور کینا، اور دیمونہ، اور عدادا، \n23۔ اور کیدیش، اور حزور، اور ایتھنان، \n24۔ زف، اور ٹیلم، اور بیلوتھ، \n25۔ اور حزور، حداتہ، اور کریوث، {اور} حزرون، جو {ہے} حزور، \n26۔ آمام، اور شمع، اور مولادہ، \n27۔ اور ہزرگداہ، اور ہشمون، اور بیت پالت، \n28۔ اور ہزارشوال، اور بیر شبع، اور بزجوتجہ، \n29۔ بعلہ، اور ایم، اور عظم، \n30۔ اور ایلٹولاد، اور چیسل، اور ہورمہ، \n31۔ اور ذکلاگ، اور مدمناہ، اور سنسانہ، \n32۔ اور لباؤت، اور شیلہیم، اور عین اور رمون: تمام شہر انتیس اور بیس ہیں، ان کے گاؤں بھی: \n33. {اور} وادی میں، اشتاول، زوریعہ اور اشناہ میں، \n34. اور زانواہ، اور اینگانیم، تپواہ، اور عنام، \n35۔ یرموتھ، اور عدلم، سوکو، اور عزیکاہ، \n36۔ اور شارائم، اور ادیتھیم، اور گدیرا، اور گیڈروتھیم؛ چودہ شہر ان کے دیہات کے ساتھ: {اور گیدروتھیم: یا، یا گیڈروتھیم}\n37۔ زینان، ہداشہ، اور مگدلگاد، \n38. اور دلیان، اور مزپیہ، اور جوکتھیل، \n39۔ لاکیش، بوزکاتھ، اور ایگلون، \n40۔ اور کابون، اور لہمام، اور کیتھلیش، \n41۔ اور گیدروت، بیت دقون، نعمہ اور مکیدا؛ سولہ شہر ان کے گاؤں کے ساتھ: \n42. لبنا، اور ایتھر، اور آشان، \n43۔ اور جفتہ، اشنا، اور نزب، \n44۔ اور کیلاہ، اور اچزیب، اور مارشاہ؛ نو شہر جن کے گاؤں تھے: \n45۔ ایکرون، اپنے شہروں اور دیہات کے ساتھ: \n46۔ ایکرون سے سمندر تک، وہ سب {جو اشدود کے قریب} کے قریب تھے، اپنے گاؤں کے ساتھ: {قریب: عبرانی۔ اس جگہ کے پاس}\n47۔ اشدود اپنے شہروں اور دیہات کے ساتھ، غزہ اپنے شہروں اور دیہات کے ساتھ، مصر کے دریا، عظیم سمندر اور اس کی سرحد تک: \n48۔ اور پہاڑوں میں، شامیر، جتیر، اور سوکوہ، \n49۔ اور دنہ، اور کرجاتسانہ، جو {ہے} دیبیر، \n50۔ اور عناب، اور اشتیموہ، اور انیم، \n51۔ اور گوشن، اور ہولون، اور گیلوہ؛ گیارہ شہر جن کے گاؤں تھے: \n52۔ عرب، دومہ اور ایشان، \n53. اور جانم، اور بیت تاپواہ، اور افیکا، {جانم: یا، یانوس}\n54۔ اور ہمتا، اور کیرجاتاربا، جو {ہے} حبرون، اور صیور؛ نو شہر جن کے گاؤں ہیں: \n55۔ ماؤن، کرمل، اور زف، اور جوتا، \n56. اور یزریل، اور یوکدیم، اور زانواہ، \n57۔ قالین، گبیعہ، اور تیمنا؛ دس شہر جن کے گاؤں تھے: \n58۔ ہلہول، بیت زور، اور گدور، \n59۔ اور مارات، اور بیثانوتھ، اور ایلٹیکون؛ چھ شہر جن کے گاؤں تھے: \n60۔ کرجاٹھبال، جو {ہے} کرجاتھجاریم، اور رباہ؛ دو شہر جن کے گاؤں ہیں: \n61۔ بیابان میں، بیتھرابا، مدین اور سیکاکاہ، \n62۔ اور نبشان، اور شہر سالٹ، اور اینگیدی؛ چھ شہر جن کے گاؤں تھے۔ \n63۔ جہاں تک یروشلم کے باشندے یبوسائیوں کا تعلق ہے، یہوداہ کے بچے انہیں نکال نہ سکے: لیکن یبوسی آج تک یروشلم میں یہوداہ کے بچوں کے ساتھ رہتے ہیں۔","1۔ اور یوسف کے بچوں کی قسمت اردن سے یریحو کے پاس، مشرق میں یریحو کے پانی تک، اور یریحو سے پہاڑ بیت ال تک اوپر جانے والے ویرانے میں گر گئی، {گرنا: عبرانی۔ روانہ ہوا}\n2۔ اور بیت ھل سے لوز جاتا ہے، اور آرکی کی سرحدوں تک آتاروت پہنچتا ہے، \n3۔ اور مغرب کی طرف یافلیتی کے ساحل، بیت حورون دی نیتھر کے ساحل تک، اور گیزر کی طرف جاتا ہے: اور وہاں سے نکلنے والے راستے سمندر کی طرف ہیں۔ \n4۔ یوں یوسف کے بیٹے، منسی اور افرائیم نے ان کی وراثت حاصل کی۔ \n5۔ اور افرائیم کے بچوں کی سرحد ان کے خاندانوں کے مطابق {یوں} تھی: یہاں تک کہ ان کی وراثت کی سرحد مشرقی طرف آتاروتھدار تھی، جو بیت حورون اوپر والے کے لیے تھی؛ \n6۔ اور سرحد سمندر کی طرف شمال میں میخمتاح تک جاتی تھی؛ اور سرحد مشرق کی طرف تعناتشیلوہ تک جاتی تھی، اور مشرق میں جانوہا تک جاتی تھی؛ \n7۔ اور وہ جانوح سے اتاروت تک نیچے گیا، پھر نارات تک، پھر یریحو پہنچا، اور اردن کی طرف روانہ ہوا۔ \n8۔ سرحد تپواہ سے مغرب کی طرف دریائے کنہ تک جاتی تھی؛ اور وہاں سے نکلنے کا راستہ سمندر کے کنارے تھا۔ یہ افرایم کے بچوں کے قبیلے کی وراثت ہے جو ان کے خاندانوں سے ملی۔ \n9۔ اور افرائیم کے بچوں کے لیے الگ الگ شہر منسی کے بچوں کی میراث میں شامل تھے، تمام شہر اور ان کے دیہات۔ \n10۔ اور وہ کنعانیوں کو نہیں نکالتے جو گیزر میں رہتے تھے، بلکہ کنعانیوں کے آج تک افریمیوں کے درمیان رہتے ہیں اور خراج کے تحت خدمت کرتے ہیں۔","1۔ منسی قبیلے کے لیے بھی بہت کچھ تھا؛ کیونکہ وہ یوسف کا پہلا بیٹا تھا؛ یعنی، مکھیر کے لیے، جو منسی کا پہلا بیٹا تھا، جو گلعاد کا باپ تھا: کیونکہ وہ جنگ پسند تھا، اس لیے اس کے پاس گلعاد اور باشان تھے۔ \n2۔ منسی کے باقی بچوں کے لیے بھی ان کے خاندانوں کی طرف سے {بہت} تھا؛ ابیزر کے بچوں کے لیے، حلیق کے بچوں کے لیے، عسریل کے بچوں کے لیے، شیکم کے بچوں کے لیے، حفار کے بچوں کے لیے، اور شمیدا کے بچوں کے لیے: یہ منسی یوسف کے بیٹے کے اپنے خاندانوں سے مرد اولاد تھے۔ {ابیزر: جسے جیزر بھی کہا جاتا ہے}\n3۔ لیکن زیلوفہد، حفیر کا بیٹا، گلعاد کا بیٹا، ماکیر کا بیٹا، منسا کا بیٹا، کے کوئی بیٹے نہیں تھے، صرف بیٹیاں تھیں: اور یہ اس کی بیٹیوں کے نام ہیں، مہلہ، نوح، حگلہ، ملکہ اور تیرزا۔ \n4۔ اور وہ الیعزر کاہن، یشوع نون کے بیٹے اور شہزادوں کے سامنے آئے، اور کہا، خداوند نے موسیٰ کو حکم دیا ہے کہ وہ ہمیں ہمارے بھائیوں میں وراثت دے۔ لہٰذا خداوند کے حکم کے مطابق اس نے انہیں ان کے باپ کے بھائیوں میں وراثت دی۔ \n5۔ اور مناسی کے دس حصے گئے، گلیعاد اور باشان کی زمین کے پاس، جو اردن کے دوسری طرف تھے؛ \n6۔ کیونکہ منسی کی بیٹیوں کو اس کے بیٹوں میں وراثت حاصل تھی: اور منسی کے باقی بیٹوں کو گلعاد کی زمین ملی۔ \n7۔ اور منسی کا ساحل آشر سے میخمتہ تک تھا، جو شیکم سے پہلے تھا؛ اور سرحد دائیں طرف انتپواہ کے باشندوں تک جاتی تھی۔ \n8. {اب} مناسی کے پاس تپواہ کی زمین تھی: لیکن منسی کی سرحد پر واقع تپواہ {افرائیم کے بچوں کی ملکیت تھی}؛ \n9۔ اور ساحل دریا قانہ دریا کے جنوب میں اترتا تھا: افرایم کے یہ شہر منسی کے شہروں میں شامل ہیں: منسی کا ساحل بھی دریا کے شمالی کنارے پر تھا، اور اس کے نکلنے والے حصے سمندر کے کنارے تھے: {دریائے کانہ: یا، سرکنڈوں کی ندی}\n10۔ جنوب کی طرف افرایم کی تھی، اور شمال کی طرف منسی کی، اور سمندر اس کی سرحد ہے؛ اور وہ شمال میں آشر اور مشرق میں اساکر میں ملے۔ \n11۔ اور منسشہ میں اساکر، آشر بیت شیان اور اس کے قصبے، اور ایبلام اور اس کے قصبے، اور دور اور اس کے قصبوں کے باشندے، اور ایندور کے باشندے اور اس کے قصبے، اور تاناج کے باشندے، اور میگیدو اور اس کے قصبوں کے باشندے، {حتیٰ کہ} تین ممالک تھے۔ \n12۔ پھر بھی منسی کے بچے ان شہروں کے باشندوں کو نکال نہ سکے؛ لیکن کنعانیوں نے اس سرزمین میں بسنا چاہا۔ \n13۔ لیکن جب بنی اسرائیل مضبوط ہو گئے، تو انہوں نے کنعانیوں کو خراج دینے پر مجبور کیا؛ لیکن انہیں مکمل طور پر نکال باہر نہیں کیا۔ \n14۔ اور یوسف کے بچوں نے یشوع سے کہا، کہ تم نے مجھے {سو} ایک پلاٹ اور ایک حصہ کیوں دیا ہے کہ میں ایک عظیم قوم ہوں، جیسا کہ خداوند نے مجھے اب تک برکت دی ہے؟ \n15۔ اور یشوع نے انہیں جواب دیا، اگر تم عظیم قوم ہو، تو پھر جنگل تک جاؤ، اور اپنے لیے وہاں پیرزیوں اور دیوؤں کی زمین پر اپنے لیے کاٹ دو، اگر پہاڑ افریم تمہارے لیے بہت تنگ ہو۔ {دیو: یا، رفیمس}\n16۔ اور یوسف کے بچوں نے کہا، پہاڑ ہمارے لیے کافی نہیں: اور تمام کنعانیوں کے جو وادی کی زمین میں رہتے ہیں، لوہے کے رتھ رکھتے ہیں، {و} جو بیت شیان اور اس کے شہروں کے ہیں، اور {و} جو {یعزریئل کی وادی کے ہیں}۔ \n17۔ اور یشوع نے یوسف خاندان سے کہا، {حتیٰ کہ} افرایم اور منسی سے بھی، کہہ دیا، 'تو ایک عظیم قوم ہو اور بہت طاقتور ہو: تمہارے پاس صرف ایک گروہ نہیں ہوگا}: \n18۔ لیکن پہاڑ تمہارا ہوگا؛ کیونکہ یہ ایک جنگل ہے، اور تم اسے کاٹنا ہوگا: اور اس کے راستے تمہارے ہوں گے: کیونکہ تم کنعانیوں کو نکال دو گے، چاہے ان کے پاس لوہے کے رتھ ہوں، {اور} چاہے وہ مضبوط ہوں۔","1۔ اور بنی اسرائیل کی پوری جماعت شیلوہ میں جمع ہوئی اور وہاں جماعت کا خیمہ قائم کیا۔ اور زمین ان کے سامنے زیر کر دی گئی۔ \n2۔ اور بنی اسرائیل میں سات قبائل باقی رہ گئے جو ابھی تک اپنی وراثت حاصل نہیں کر پائے تھے۔ \n3۔ اور یشوع نے بنی اسرائیل سے کہا، کتنی دیر تک تم اس زمین پر قبضہ کرنے کے لیے سستی کرتے ہو، جو تمہارے باپ اجداد کے خداوند خدا نے تمہیں دی ہے؟ \n4. اپنے میں سے تین آدمی ہر قبیلے کے لیے دے دو، اور میں انہیں بھیجوں گا، اور وہ اٹھیں گے، زمین میں جائیں گے، اور اپنی وراثت کے مطابق اسے بیان کریں گے؛ اور وہ دوبارہ میرے پاس آئیں گے۔ \n5۔ اور وہ اسے سات حصوں میں تقسیم کریں گے: یہوداہ ان کے ساحل پر جنوب میں رہے گا، اور یوسف کا گھرانہ شمال میں اپنے ساحلوں پر قائم ہوگا۔ \n6۔ لہٰذا تم زمین کو سات حصوں میں بیان کرو گے، اور {تفصیل} کو میرے پاس لے آؤ تاکہ میں تمہارے لیے یہاں خداوند ہمارے خدا کے سامنے قرعہ ڈال سکوں۔ \n7۔ لیکن لاویوں کا تم میں کوئی حصہ نہیں؛ کیونکہ خداوند کی کاہن ان کی وراثت ہے: اور گاد، روبن اور منسی قبیلے کا آدھا حصہ مشرق میں اردن کے پار اپنی وراثت حاصل کر چکے ہیں، جو موسیٰ خداوند کے خادم نے انہیں دی تھی۔ \n8۔ اور مرد اٹھے اور چلے گئے، اور یشوع نے ان لوگوں کو حکم دیا جو زمین کی وضاحت کرنے گئے تھے، کہا، جاؤ اور زمین میں چلو، اور اسے بیان کرو، اور دوبارہ میرے پاس آؤ، تاکہ میں یہاں شیلوہ میں خداوند کے سامنے تمہارے لیے قرعہ ڈال دوں۔ \n9۔ اور مرد گئے اور زمین سے گزرے، اور اسے شہروں کے حساب سے سات حصوں میں ایک کتاب میں بیان کیا، اور پھر {دوبارہ} یشوع کے پاس شیلوہ کے لشکر کے پاس آئے۔ \n10۔ اور یشوع نے ان کے لیے شیلوہ میں خداوند کے سامنے قرعہ ڈالا: اور وہاں یشوع نے زمین بنی اسرائیل کو ان کی تقسیم کے مطابق تقسیم کر دی۔ \n11۔ اور بنیامین کے بچوں کے قبیلے کی قسمت ان کے خاندانوں کے مطابق آ گئی: اور ان کی قسمت یہوداہ کے بچوں اور یوسف کے بچوں کے درمیان نکل آئی۔ \n12۔ اور ان کی سرحد شمالی طرف اردن سے تھی؛ اور سرحد شمالی طرف یریحو کے کنارے تک جاتی تھی، اور پہاڑوں کے ذریعے مغرب کی طرف جاتی تھی؛ اور وہاں سے نکلنے کا راستہ بیت ہاون کے ویرانے میں تھا۔ \n13۔ اور سرحد وہاں سے لوز کی طرف جاتی تھی، لوز کے کنارے پر، جو {ہے} بیت ھل، جنوب کی طرف؛ اور سرحد اتروتھادار تک اترتی تھی، جو اس پہاڑی کے قریب {لیتھ} ہے جو نیدر بیتھرون کے جنوب میں واقع ہے۔ \n14۔ اور سرحد {وہاں سے} کھینچی گئی، اور سمندر کے کونے کو جنوب کی طرف گھیر لیتی، اس پہاڑی سے جو بیت حورون سے پہلے جنوب کی طرف واقع تھی؛ اور وہاں سے نکلنے کا راستہ کیرجاتھبال میں تھا، جو {ہے} کرجاتجاریم ہے، یہوداہ کے بچوں کا شہر: یہ {تھا} مغربی حصہ تھا۔ \n15۔ اور جنوبی حصہ کیرجاتجاریم کے آخر سے تھا، اور سرحد مغرب کی طرف جاتی تھی، اور نفطوح کے پانیوں کے کنویں تک جاتی تھی: \n16۔ اور سرحد اس پہاڑ کے آخر تک آتی تھی جو {ہینوم' کے بیٹے کی وادی سے پہلے واقع ہے، {اور} جو {ہے} شمال میں دیوؤں کی وادی میں، اور جنوب میں ہینوم کی وادی میں اترتی ہے، یبوسی کے کنارے پر، اور اینروگل تک اتر جاتی ہے، \n17۔ اور شمال سے کھینچا گیا، اور انشمیش کی طرف روانہ ہوا، اور گیلیلوت کی طرف روانہ ہوا، جو ادومیم کے اوپر جانے کے خلاف ہے، اور بوہان کے پتھر پر اتر آیا، جو روبن کا بیٹا تھا، \n18۔ اور عربہ کے خلاف شمال کی طرف رخ کیا، اور عربہ کی طرف نیچے چلا گیا: {عربہ: یا، میدان}\n19۔ اور سرحد شمال کی طرف بیت ہوگلہ کے کنارے سے گزرتی تھی: اور سرحد کے باہر جانے والے راستے نمک سمندر کے شمالی خلیج میں اردن کے جنوبی سرے پر تھے: یہ {تھا} جنوبی ساحل۔ {خلیج: عبرانی۔ زبان}\n20۔ اور اردن اس کی مشرقی طرف سرحد تھی۔ یہ بنیامین کے بچوں کی وراثت تھی، جو اس کے آس پاس کے کنارے واقع تھے، ان کے خاندانوں کے مطابق۔ \n21۔ اب بنیامین کے بچوں کے قبیلے کے شہر ان کے خاندانوں کے مطابق یریحو، بیت ہوگلہ اور وادی قزیز تھے، \n22۔ اور بیتھارابا، اور زمارائم، اور بیت ایل، \n23۔ اور اویم، اور پارہ، اور اوفرا، \n24۔ اور چیفرہاممونائی، اوفنی، اور گابا؛ بارہ شہر ان کے دیہات کے ساتھ: \n25۔ گبیون، اور رامہ، اور بیروت، \n26. اور مزپہ، اور چفیرا، اور موزاہ، \n27۔ اور ریکیم، اور ارپیل، اور تارالہ، \n28۔ اور زلاہ، ہاتھی، اور یبوسی، جو {ہے} یروشلم، گبیث، {اور} کرجات؛ چودہ شہر ان کے گاؤں کے ساتھ۔ یہ {ہے} بنیامین کے بچوں کی وراثت ان کے خاندانوں کے مطابق۔","1۔ اور دوسرا قرعہ شمعون کے پاس آیا، {حتیٰ کہ} کہ شمعون کی اولاد کے قبیلے کے لیے ان کے خاندانوں کے مطابق: اور ان کی میراث یہوداہ کے بچوں کی وراثت میں تھی۔ \n2۔ اور ان کی وراثت میں بیرشبع، یا سبا، اور مولادہ تھے، \n3۔ اور حزرشوال، اور بالاح، اور عظم، \n4۔ اور ایلتولاد، اور بیتول، اور ہورمہ، \n5۔ اور زیکلاگ، اور بیت مرقبوت، اور حزارسوسا، \n6۔ اور بیت لباؤتھ، اور شاروہن؛ تیرہ شہر اور ان کے گاؤں: \n7. عین، ریمون، اور ایتھر، اور آشان؛ چار شہر اور ان کے گاؤں: \n8۔ اور ان شہروں کے ارد گرد تمام گاؤں جو جنوب کے رامتھ بعلثبیر تک تھے۔ یہ قبیلے کی وراثت ہے جو شمعون کے بچوں کے خاندانوں کے مطابق ہے۔ \n9۔ یہوداہ کے بچوں کے حصے میں سے شمعون کے بچوں کی وراثت تھی: کیونکہ یہوداہ کے بچوں کا حصہ ان کے لیے بہت زیادہ تھا؛ اس لیے شمعون کے بچوں کی وراثت ان کی وراثت میں تھی۔ \n10۔ اور تیسرا قرعہ زبولون کے بچوں کے لیے ان کے خاندانوں کے مطابق آیا: اور ان کی وراثت کی سرحد سارد تک تھی: \n11۔ اور ان کی سرحد سمندر اور مارالہ کی طرف جاتی تھی، اور دباشیت تک پہنچی، اور اس دریا تک پہنچی جو یوکنام کے سامنے ہے؛ \n12۔ اور سرید سے مشرق کی طرف سورج نکلنے کی طرف چسلوثتابور کی سرحد تک مڑا، پھر دابیرات کی طرف روانہ ہوا، اور یافیہ کی طرف چڑھا، \n13۔ اور وہاں سے مشرق کی طرف گٹاہفر کی طرف جاتا ہے، پھر اٹاہکازین جاتا ہے، اور ریمونمیتھوار کی طرف نیاہ تک جاتا ہے؛ {میتھوآر: یا، جو کھینچا جاتا ہے}\n14۔ اور سرحد اسے شمالی جانب ہناتھون تک گھیرے ہوئے ہے: اور اس کے اخراجات جفتاہل کی وادی میں ہیں: \n15۔ اور کتات، اور نہلال، اور شمرون، اور ایدالہ، اور بیت لحم: بارہ شہر ان کے دیہات کے ساتھ۔ \n16. یہ زبولون کے بچوں کی وراثت ہے ان کے خاندانوں کے مطابق، یہ شہر ان کے دیہات کے ساتھ۔ \n17۔ {اور} چوتھا قرعہ اساکر کے لیے آیا، یساکر کے بچوں کے لیے ان کے خاندانوں کے مطابق۔ \n18۔ اور ان کی سرحد یزریل، چیسولوتھ، اور شونیم کی طرف تھی، \n19۔ اور ہفرائیم، اور شیون، اور انہارتھ، \n20۔ اور ریبتھ، اور کیشیون، اور ابیز، \n21۔ اور رمیت، اور اینگانیم، اور انحداہ، اور بیت پازیز؛ \n22۔ اور ساحل تابور، شہازیمہ، اور بیت شمش تک پہنچتا ہے؛ اور ان کی سرحد کے اخراجات اردن تک تھے: سولہ شہر ان کے دیہات کے ساتھ۔ \n23۔ یہ اسکار کے بچوں کے قبیلے کی وراثت ہے، ان کے خاندانوں، شہروں اور دیہات کے مطابق۔ \n24۔ اور پانچواں قرعہ آشر کے بچوں کے قبیلے کے خاندانوں کے مطابق نکلا۔ \n25۔ اور ان کی سرحد ہیلکات، ہالی، بیٹن اور اخشاف تھی، \n26۔ اور الامیلیک، اور عماد، اور مشیل؛ اور مغرب کی طرف کرمل تک، اور شہورلیبناتھ تک؛ \n27۔ اور طلوع آفتاب کی طرف مڑتا ہے، بیت داگون کی طرف، زبولون، اور جفتاہل کی وادی کی طرف بثمیک اور نیئل کی طرف جاتا ہے، اور بائیں طرف کابل کی طرف جاتا ہے، \n28۔ اور حبرون، اور رحوب، اور ہامون، اور قانا، {حتی} عظیم زیدون تک؛ \n29۔ اور {پھر} ساحل رامہ کی طرف مڑتا ہے، اور مضبوط شہر صور کی طرف؛ اور ساحل ہوساہ کی طرف مڑتا ہے؛ اور اس کے اخراجات ساحل سے اخزیب تک سمندر کے کنارے ہیں: {صور: عبرانی۔ تزور}\n30۔ امت بھی، افیق، اور رحوب: بائیس شہر اپنے دیہات کے ساتھ۔ \n31۔ یہ آشیر کے بچوں کے قبیلے کی وراثت ہے، ان کے خاندانوں کے مطابق، یہ شہر اپنے گاؤں کے ساتھ۔ \n32۔ چھٹا قرعہ نفتالی کے بچوں کے لیے آیا، {حتیٰ کہ} نفتالی کے بچوں کے لیے ان کے خاندانوں کے مطابق۔ \n33۔ اور ان کا ساحل ہیلیف سے تھا، الون سے زانانیم تک، اور آدمی، نکب، اور جبنیل سے لاکوم تک؛ اور اس کا سفر اردن میں تھا: \n34۔ اور {پھر} ساحل مغرب کی طرف ازنوتھبور کی طرف مڑتا ہے، وہاں سے ہکاک تک جاتا ہے، جنوب میں زبولون تک پہنچتا ہے، مغرب میں آشر تک پہنچتا ہے، اور سورج نکلنے کی طرف یردن پر یہوداہ تک پہنچتا ہے۔ \n35۔ اور باڑ والے شہر زدیم، زر، اور ہمتھ، راکٹھ، اور چنریٹھ ہیں، \n36۔ اور آدمہ، اور رامہ، اور حزور، \n37. اور کیدیش، اور ادری، اور اینہازور، \n38۔ اور لوہا، اور مگدالیل، ہورم، اور بیتھاناتھ، اور بیت شمش؛ انیس شہر ان کے گاؤں کے ساتھ۔ \n39۔ یہ نفتالی کے بچوں کے قبیلے کی وراثت ہے جو ان کے خاندانوں، شہروں اور دیہات کے مطابق ہے۔ \n40۔ {اور} ساتواں قرعہ دان کے بچوں کے قبیلے کے خاندانوں کے مطابق نکلا۔ \n41۔ اور ان کی وراثت کا ساحل زورہ، اشٹاول، اور ارشمش تھا، \n42. اور شالابین، اور اجلون، اور جثلہ، \n43. اور ایلون، اور تھمناتاہ، اور ایکرون، \n44۔ اور التیکہ، اور گبتھن، اور بعالت، \n45۔ اور یہود، اور بینیبیرک، اور جثریمون، \n46۔ اور میجارکون، اور راکون، جس کی سرحد جافو سے پہلے ہے۔ {پہلے: یا، مخالفت میں} {جافو: یا، جوپا}\n47۔ اور دان کے بچوں کا ساحل ان کے لیے {بہت چھوٹا} باہر نکلا، اس لیے دان کے بچے لشم کے خلاف لڑنے گئے، اسے لے کر تلوار کے دھار سے مارا اور اس پر قبضہ کر لیا، اور وہاں بسنے لے، اور لشم کو دان کہا، جو دان کے نام پر تھا، جو ان کے والد دان کے نام پر تھا۔ \n48۔ یہ قبیلے کی وراثت ہے جو دان کے بچوں کے خاندانوں کے مطابق ہے، یہ شہر اپنے گاؤں کے ساتھ۔ \n49۔ جب انہوں نے اپنے ساحلوں سے وراثت کے لیے زمین تقسیم کرنا ختم کر دیا، تو بنی اسرائیل نے ان میں سے نون کے بیٹے یشوع کو وراثت دی: \n50۔ خداوند کے کلام کے مطابق انہوں نے اسے وہ شہر دیا جس سے اس نے درخواست کی تھی، {حتیٰ کہ} تیمناثسرہ بھی افرائیم پہاڑ میں: اور اس نے شہر تعمیر کیا اور وہاں رہا۔ \n51۔ یہ وہ وراثتیں ہیں جو الیعزر کاہن، یشوع نون کے بیٹے، اور بنی اسرائیل کے قبائل کے باپوں کے سروں نے شیلوہ میں خدا کے سامنے جماعت کے خیمہ کے دروازے پر قرعہ اندازی کے لیے تقسیم کی۔ یوں انہوں نے ملک کی تقسیم کا خاتمہ کیا۔","1۔ خداوند نے بھی یشوع سے کہا، \n2۔ بنی اسرائیل سے فرماو، کہو، اپنے لیے پناہ کے شہر مقرر کرو، جن کے بارے میں میں نے موسیٰ کے ہاتھوں تم سے بات کی تھی: \n3۔ تاکہ وہ قاتل جو کسی کو بے خبری میں قتل کرے {اور} انجانے میں وہاں بھاگ جائے: اور وہ خون کے انتقام لینے والے سے تمہاری پناہ گاہ بنے۔ \n4۔ اور جب جو ان شہروں میں سے کسی ایک کی طرف بھاگے گا وہ شہر کے دروازے کے دروازے پر کھڑا ہوگا، اور اس شہر کے بزرگوں کے کانوں میں اپنا موقف بیان کرے گا، تو وہ اسے شہر میں لے جائیں گے اور اسے ایک جگہ دیں گے تاکہ وہ ان کے درمیان رہ سکے۔ \n5۔ اور اگر خون کا انتقام لینے والا اس کا پیچھا کرے، تو وہ قاتل کو اس کے ہاتھ میں نہیں دے سکتے؛ کیونکہ اس نے اپنے پڑوسی کو انجانے میں مارا اور پہلے سے نفرت نہیں کی۔ \n6۔ اور وہ اس شہر میں رہے گا، جب تک کہ وہ جماعت کے سامنے عدالت کے لیے کھڑا نہ ہو جائے، {اور} جب تک کہ ان دنوں اعلیٰ پادری کی موت نہ ہو جائے: پھر قاتل واپس آئے گا، اور اپنے شہر اور اپنے گھر آئے گا، اس شہر میں جہاں سے وہ بھاگا تھا۔ \n7۔ انہوں نے گلیل میں کدش کو کوہ نفتالی میں، اور شیخیم کو افرائیم پہاڑ میں، اور کیرجاتھاربا کو، جو کہ {ہے} ہیبرون ہے، یہوداہ کے پہاڑ میں مقرر کیا۔ {مقرر: عبرانی۔ مقدس}\n8۔ اور اردن کے دوسری طرف یریحو کے مشرق کی طرف، انہوں نے بزر کو رابن قبیلے کے میدان میں بیابان میں، اور راموت کو گیلاد میں گاد کے قبیلے سے، اور گولان کو باشان میں منسی قبیلے سے مقرر کیا۔ \n9۔ یہ وہ شہر تھے جو تمام بنی اسرائیل کے لیے مقرر کیے گئے تھے، اور ان کے درمیان رہنے والے اجنبی کے لیے، تاکہ جو کوئی بھی شخص اچانک قتل کرے وہ وہاں بھاگ جائے اور خون کے انتقام لینے والے کے ہاتھوں نہ مرے، جب تک کہ وہ جماعت کے سامنے کھڑا نہ ہو۔","1۔ پھر لاویوں کے باپ اجداد کے سر الیعزر کاہن، یشوع نون کے بیٹے، اور بنی اسرائیل کے قبائل کے باپوں کے سروں کے پاس آئے؛ \n2۔ اور انہوں نے کنعان کی سرزمین شیلوہ میں ان سے کہا، کہا کہ خداوند نے موسیٰ کے ہاتھوں حکم دیا ہے کہ ہمیں ایسے شہر دے جہاں ہم رہ سکیں، اور اس کے مضافات بھی ہمارے مویشیوں کے لیے۔ \n3۔ اور بنی اسرائیل نے لاویوں کو ان کی میراث سے، خداوند کے حکم پر، یہ شہر اور ان کے مضافات دے دیے۔ \n4۔ اور یہ قرعہ کوہتیوں کے خاندانوں کے لیے آیا: اور ہارون کاهن کے بیٹے، جو لاویوں کے تھے، نے یہوداہ قبیلے سے، شمعون قبیلے سے، اور بنیامین قبیلے سے تیرہ شہر قرعہ اندازی کیے۔ \n5۔ اور کوہات کے باقی بچوں کو قبیلہ افرائیم کے خاندانوں سے، قبیلہ دان سے، اور مناسی کے آدھے قبیلے میں سے قرعہ اندازی کے ذریعے دس شہر ملے۔ \n6۔ اور گرشون کی اولاد نے قبیلہ اساکر کے خاندانوں سے، آشر قبیلے سے، نفتالی قبیلے سے، اور باشان میں منسی کے آدھے قبیلے سے تیرہ شہر حاصل کیے۔ \n7۔ مراری کے بچوں نے اپنے خاندانوں سے روبن قبیلے سے، گاد قبیلے سے، اور زبولون قبیلے سے بارہ شہر پیدا کیے۔ \n8۔ اور بنی اسرائیل نے لاویوں کو قرعہ ڈال کر یہ شہر اور ان کے مضافات دیے، جیسا کہ خداوند نے موسیٰ کے ہاتھ سے حکم دیا۔ \n9۔ اور انہوں نے یہوداہ کے بچوں کے قبیلے اور شمعون کے بچوں کے قبیلے سے یہ شہر دیے، جن کا {یہاں} نام سے ذکر کیا گیا ہے، {ذکر شدہ: عبرانی۔ کہا جاتا ہے}\n10۔ جو کہ ہارون کی اولاد، جو کوہتیوں کے خاندانوں سے تھے، جو لاوی کے بچوں میں سے تھے، کے پاس تھے: کیونکہ ان کا پہلا حصہ تھا۔ \n11۔ اور انہوں نے انہیں عناک کے والد اربا شہر دیا، جو {شہر} ہیبرون ہے، یہوداہ کی پہاڑی {ملک} میں، اور اس کے گرد کے مضافات ہیں۔ {شہر...: یا، کرجاتاربا}\n12۔ لیکن شہر کے کھیتوں اور اس کے دیہات نے انہیں کیلب کے بیٹے یفونیہ کو اس کی ملکیت کے لیے دے دیا۔ \n13۔ یوں انہوں نے ہارون کے بچوں کو کاهن ہیبرون کو اس کے مضافات کے ساتھ قاتل کے لیے پناہ گاہ کا شہر دیا؛ اور لبنہ کو اس کے مضافات کے ساتھ، \n14۔ اور جتیر اپنے مضافات کے ساتھ، اور اشتیموآ اپنے مضافات کے ساتھ، \n15۔ اور ہولون اپنے مضافات کے ساتھ، اور دیبیر اپنے مضافات کے ساتھ، {ہولون: جسے ہیلن بھی کہا جاتا ہے}\n16۔ اور عین اپنے مضافات کے ساتھ، اور یوتاہ اپنے مضافات کے ساتھ، {اور} بیت شمش اپنے مضافات کے ساتھ؛ ان دو قبائل میں سے نو شہر۔ {عین: جسے آشان بھی کہا جاتا ہے}\n17۔ اور بنیامین قبیلے سے، گبعون اپنے مضافات کے ساتھ، گیبا اپنے مضافات سے، {گیبا: جسے گابا بھی کہا جاتا ہے}\n18۔ اناتھوتھ اپنے مضافات کے ساتھ، اور المون اپنے مضافات کے ساتھ؛ چار شہر۔ {المون: جسے الیمت بھی کہا جاتا ہے}\n19۔ ہارون کے بچوں کے تمام شہر، یعنی کاہن، تیرہ شہر تھے جن کے مضافات تھے۔ \n20۔ اور کوہات کے بچوں کے خاندان، لاوی جو کوہات کے بچوں میں سے باقی رہ گئے، حتیٰ کہ انہوں نے بھی افرایم قبیلے سے اپنی قسمت کے شہر حاصل کر لیے۔ \n21۔ کیونکہ انہوں نے انہیں شیکم اور اس کے مضافات کوہ افرائیم میں دیے، {جو قاتل کے لیے پناہ گاہ بنے}؛ اور گیزر اپنے مضافات کے ساتھ، \n22۔ اور کیبزیم اپنے مضافات کے ساتھ، اور بیت حورون اپنے مضافات کے ساتھ؛ چار شہر۔ \n23۔ اور دان کے قبیلے سے، التیکہ اپنے مضافات کے ساتھ، گبتھون اپنے مضافات کے ساتھ، \n24۔ ایجالون اپنے مضافات کے ساتھ، گاتھرمون اپنے مضافات کے ساتھ؛ چار شہر۔ \n25۔ اور مناسی کے نصف قبیلے میں سے، تنخ اپنے مضافات کے ساتھ، اور گاتھرمون اپنے مضافات کے ساتھ؛ دو شہر۔ \n26۔ تمام شہر دس تھے جن کے مضافات کوہاتھ کے بچوں کے خاندانوں کے لیے تھے۔ \n27۔ اور گرشون کے بچوں کو، لاویوں کے خاندانوں سے، منسی کے {دوسرے} نصف قبیلے سے {انہوں نے} گولان کو باشان میں اس کے مضافات کے ساتھ دیا، {جو قاتل کے لیے پناہ گاہ بن جائے}؛ اور بیشترہ کو اس کے مضافات کے ساتھ؛ دو شہر۔ \n28۔ اور قبیلہ اسکار سے، کیشون اپنے مضافات کے ساتھ، دبارہ اپنے مضافات سے، \n29۔ جارموتھ اپنے مضافات کے ساتھ، اینگانم اپنے مضافات کے ساتھ؛ چار شہر۔ \n30۔ اور آشر قبیلے سے، مشعل اپنے مضافات کے ساتھ، عبدون اپنے مضافات کے ساتھ، \n31۔ ہیلکاتھ اپنے مضافات کے ساتھ، اور ریہوب اپنے مضافات کے ساتھ؛ چار شہر۔ \n32۔ اور نفتالی قبیلے سے، گلیل میں کیدیش اپنے مضافات کے ساتھ، {جو قاتل کے لیے پناہ کا شہر بنے}؛ اور ہموتھدور اپنے مضافات کے ساتھ، اور کارتن اپنے مضافات کے ساتھ؛ تین شہر۔ \n33۔ گرشونیوں کے تمام شہر ان کے خاندانوں کے مطابق تیرہ شہر تھے جن کے مضافات بھی تھے۔ \n34۔ اور مراری کے بچوں کے خاندانوں کو، باقی لاویوں کو، قبیلہ زبولون سے، یوکنام اپنے مضافات کے ساتھ، اور کارتاہ کے مضافات کے لیے، \n35۔ دمنہ اپنے مضافات کے ساتھ، نہلال اپنے مضافات کے ساتھ؛ چار شہر۔ \n36۔ اور روبن قبیلے سے، بیزر اپنے مضافات کے ساتھ، اور جہازہ اپنے مضافات سے، \n37۔ کیدیموتھ اپنے مضافات کے ساتھ، اور میفاتھ اپنے مضافات کے ساتھ؛ چار شہر۔ \n38۔ اور گاد قبیلے سے، گلعاد میں راموت اور اس کے مضافات، جو قاتل کے لیے پناہ گاہ بننے والا ہے؛ اور مہنائیم اپنے مضافات کے ساتھ، \n39۔ ہیشبون اپنے مضافات کے ساتھ، جازر اپنے مضافات کے ساتھ؛ کل چار شہر۔ \n40۔ تو مراری کے بچوں کے لیے جو شہر ان کے خاندانوں کے لیے تھے، جو لاویوں کے خاندانوں میں سے باقی تھے، ان کے بارہ شہر بن گئے۔ \n41۔ لاویوں کے تمام شہر جو بنی اسرائیل کے قبضے میں تھے، چالیس اور اٹھاسی شہر تھے جن کے مضافات بھی تھے۔ \n42۔ یہ شہر ہر ایک تھے جن کے ارد گرد مضافات تھے: یوں یہ تمام شہر {تھے}۔ \n43۔ اور خداوند نے اسرائیل کو وہ ساری زمین دی جو اس نے اپنے باپ اجداد کو دینے کی قسم کھائی تھی؛ اور انہوں نے اس زمین پر قبضہ کر لیا اور وہاں بسے۔ \n44۔ اور خداوند نے انہیں اپنے باپ دادا سے جو قسم کھائی تھی، اس کے مطابق آرام دیا: اور ان کے تمام دشمنوں میں سے کوئی ان کے سامنے کھڑا نہ تھا؛ خداوند نے ان کے تمام دشمنوں کو ان کے ہاتھ میں دے دیا۔ \n45۔ خداوند کی طرف سے اسرائیل کے گھر سے کوئی اچھی بات نہیں ہونی چاہیے تھی؛ سب کچھ ہوا۔","1۔ پھر یشوع نے روبن کے لوگوں، اور گدائیوں کو، اور منسی کے آدھے قبیلے کو بلایا، \n2۔ اور میں نے ان سے کہا، تم نے وہ سب کچھ نبھایا جو موسیٰ خداوند کے خادم نے تمہیں حکم دیا تھا، اور میری آواز کی اطاعت کی جو میں نے تمہیں حکم دی: \n3۔ تم نے آج تک اپنے بھائیوں کو نہیں چھوڑا، بلکہ خداوند تمہارے خدا کے حکم کی ذمہ داری پوری کی ہے۔ \n4۔ اور اب خداوند تمہارے خدا نے تمہارے بھائیوں کو آرام دیا ہے، جیسا کہ اس نے ان سے وعدہ کیا تھا: لہٰذا اب تم واپس جاؤ، اور اپنے خیموں میں جاؤ، {اور} اپنی ملکیت کی زمین پر، جو موسیٰ خداوند کے خادم نے تمہیں اردن کے دوسری طرف دی تھی۔ \n5۔ لیکن اس حکم اور قانون پر پوری توجہ سے عمل کرو، جو موسیٰ، خداوند کے بندے نے تمہیں حکم دیا ہے، کہ خداوند تمہارے خدا سے محبت کرو، اس کے تمام راستوں پر چلو، اس کے احکامات کی پاسداری کرو، اس سے چمٹو، اور پورے دل و جان سے اس کی خدمت کرو۔ \n6۔ تو یشوع نے انہیں برکت دی اور بھیج دیا، اور وہ اپنے خیموں میں چلے گئے۔ \n7۔ اب منسی قبیلے کے {ایک} حصے کو، موسیٰ نے باشان میں {قبضہ} دیا تھا، لیکن {باقی} آدھے حصے کو یشوع کو اس طرف اپنے بھائیوں میں سے یشوع کو مغرب کی طرف اردن دیا۔ اور جب یشوع نے انہیں بھی ان کے خیموں میں بھیجا، تو اس نے انہیں برکت دی، \n8۔ اور اس نے ان سے کہا، \"بہت دولت کے ساتھ اپنے خیموں، بہت سا مویشی، چاندی، سونا، پیتل، لوہا اور بہت زیادہ لباس کے ساتھ واپس آؤ، اپنے دشمنوں کا مال اپنے بھائیوں میں تقسیم کرو۔ \n9۔ اور روبن کے بچے اور گاد کے بچے اور منسی کے آدھے قبیلے واپس آئے، اور بنی اسرائیل سے شیلوہ سے روانہ ہوئے، جو کنعان کی سرزمین میں ہے، تاکہ وہ گلعاد کے ملک کی طرف جا سکیں، جو ان کی ملکیت تھی، جہاں وہ موسیٰ کے کلام کے مطابق اپنے قبضے میں تھے۔ \n10۔ اور جب وہ اردن کی سرحدوں پر پہنچے، جو کنعان کی سرزمین میں ہیں، تو روبن کے بیٹے، جاد کے بچے اور منسی کے آدھے قبیلے نے وہاں اردن کے پاس ایک قربان گاہ بنائی، جو ایک عظیم قربان گاہ تھی۔ \n11۔ اور بنی اسرائیل نے سنا کہ دیکھو، روبن کے بیٹے، گاد کے بچے اور منسی کے آدھے قبیلے نے کنعان کی زمین کے پار، اردن کی سرحدوں پر، بنی اسرائیل کے گزرنے پر ایک قربان گاہ تعمیر کی ہے۔ \n12۔ اور جب بنی اسرائیل نے اس کے بارے میں سنا، تو بنی اسرائیل کی پوری جماعت شیلوہ میں جمع ہو گئی تاکہ ان کے خلاف جنگ کریں۔ \n13۔ اور بنی اسرائیل نے روبن کے بیٹے، اور گاد کے بچوں کو، اور منسی کے آدھے قبیلے کو گلعاد کی سرزمین میں بھیجا، فینیحاس، جو الیعزر کاهن کا بیٹا تھا، \n14۔ اور اس کے ساتھ دس شہزادے تھے، ہر سردار خاندان سے اسرائیل کے تمام قبائل میں ایک شہزادہ تھا؛ اور ہر ایک اپنے باپ و اجداد کے گھر کا سربراہ تھا، جو ہزاروں اسرائیل میں تھا۔ {سردار...: عبرانی۔ باپ کا گھر}\n15۔ اور وہ روبن کے بچوں کے پاس، اور گاد کے بچوں اور منسی کے آدھے قبیلے کے پاس گلعاد کی زمین پر آئے، اور ان سے بات کی، کہا، \n16۔ خداوند کی پوری جماعت یوں فرماتی ہے، یہ کیا گناہ ہے جو تم نے اسرائیل کے خدا کے خلاف کی ہے، کہ آج تم نے خداوند کی پیروی سے منہ موڑ لیا، کیونکہ تم نے اپنے لیے ایک قربان گاہ بنائی ہے، تاکہ آج تم خداوند کے خلاف بغاوت کر سکو؟ \n17. کیا پیور کی بدکاری ہمارے لیے بہت کم ہے، جس سے ہم آج تک پاک نہیں ہوئے، حالانکہ خداوند کی جماعت میں وبا تھی، \n18. لیکن آج تم خدا کی پیروی سے منہ موڑو؟ اور یہ ہوگا، {دیکھتے ہوئے} کہ تم آج خداوند کے خلاف بغاوت کرتے ہو، کہ کل وہ پورے اسرائیل کی جماعت سے ناراض ہوگا۔ \n19۔ اگرچہ اگر آپ کی ملکیت کی زمین {ناپاک} ہے، تو {تو} آپ خداوند کی ملکیت کی زمین میں منتقل ہو جائیں، جہاں خداوند کا خیمہ رہتا ہے، اور ہمارے درمیان قبضہ کر لیں: لیکن خداوند کے خلاف بغاوت نہ کریں، اور نہ ہی ہمارے خلاف بغاوت کریں کہ آپ کو خداوند ہمارے خدا کے قربان گاہ کے پاس ایک قربان گاہ تعمیر کرنی ہے۔ \n20. کیا عچان، زرا کا بیٹا، اس چیز میں گناہ نہیں کر رہا تھا، اور تمام اسرائیل کی جماعت پر غصہ نہیں آیا؟ اور وہ آدمی اپنی گناہوں میں اکیلا ہلاک نہیں ہوا۔ \n21۔ پھر روبن کے بیٹے، گاد کے بچے اور منسی کے آدھے قبیلے نے جواب دیا اور ہزاروں اسرائیلیوں کے سروں سے کہا، \n22۔ خداوں کے خداوند خدا، خداوں کا خداوند خدا، وہ جانتا ہے، اور اسرائیل کو معلوم ہوگا؛ اگر وہ بغاوت میں ہو، یا اگر خداوند کے خلاف گناہ میں ہو، (آج ہمیں نہ بچائے،)\n23۔ کہ ہم نے اپنے لیے ایک قربان گاہ بنائی ہے تاکہ ہم خداوند کی پیروی کرنے سے بچ سکیں، یا اگر اس پر جلنے والی قربانی یا گوشت کی قربانی پیش کریں، یا اگر صلح کی قربانیاں پیش کریں تو خداوند خود اس کا تقاضا کرے؛ \n24. اور اگر ہم نے یہ {بلکہ} اس خوف سے نہیں کیا کہ {اس} چیز کہیں، کہ آنے والے وقت میں تمہارے بچے ہمارے بچوں سے بات کر سکتے ہیں، کہہ سکتے ہیں، تمہارا رب اسرائیل کے خدا سے کیا تعلق ہے؟ {وقت کے ساتھ...: عبرانی۔ کل کے لیے}\n25۔ کیونکہ خداوند نے اردن کو ہمارے اور آپ کے درمیان سرحد بنا دیا ہے، اے روبن کی اولاد اور گاد کے بیٹے؛ آپ کا خداوند میں کوئی حصہ نہیں: اسی طرح آپ کے بچے ہمارے بچوں کو خداوند سے ڈرنے سے باز رکھیں گے۔ \n26۔ لہٰذا ہم نے کہا، آئیے اب اپنے لیے قربان گاہ بنانے کی تیاری کریں، نہ جلانے کے لیے اور نہ قربانی کے لیے: \n27. لیکن {تاکہ} یہ ہمارے درمیان، تمہارے درمیان، اور ہماری بعد کی نسلوں کے درمیان گواہی ہو کہ ہم خداوند کی خدمت اس کے سامنے اپنے جلانے والے قربانیاں، قربانیوں اور امن کی قربانیوں کے ساتھ انجام دے سکیں؛ تاکہ تمہارے بچے آنے والے وقت میں ہمارے بچوں سے نہ کہیں، تمہارا خداوند میں کوئی حصہ نہیں۔ \n28۔ لہٰذا ہم نے کہا کہ جب وہ ہمیں یا ہماری آنے والی نسلوں سے یہ کہیں گے، تاکہ ہم دوبارہ کہیں، دیکھو خداوند کے مذبح کا نمونہ جو ہمارے آباؤ اجداد نے بنایا تھا، نہ تو جلانے کی قربانیوں کے لیے، نہ قربانی کے لیے؛ بلکہ یہ ہمارے اور تمہارے درمیان گواہی ہے۔ \n29. خدا نہ کرے کہ ہم خداوند کے خلاف بغاوت کریں، اور آج خداوند کی پیروی سے ہٹ جائیں، اور خداوند ہمارے خدا کے مذبح کے پاس جلانے کی قربان گاہ بنائیں۔ \n30۔ اور جب فینیحاس کاہن، جماعت کے شہزادے اور ہزاروں اسرائیل کے سربراہ جو اس کے ساتھ تھے، نے وہ الفاظ سنے جو روبن کے بیٹے، گاد کے بچے اور منسی کے بچوں نے کہے، تو وہ خوش ہوئے۔ {خوش...: عبرانی۔ ان کی نظر میں اچھا تھا}\n31۔ اور فینیحاس، جو الیعزر کا بیٹا تھا، نے روبن کے بیٹے، گاد کے بچوں اور منسی کے بچوں سے کہا، آج ہم دیکھتے ہیں کہ خداوند ہمارے درمیان ہے، کیونکہ تم نے خداوند کے خلاف یہ گناہ نہیں کیا: اب تم نے بنی اسرائیل کو خداوند کے ہاتھوں سے آزاد کر دیا ہے۔ {اب: عبرانی۔ تو}\n32۔ اور فینیحاس، جو الیعزر کاهن کا بیٹا تھا، اور شہزادے، روبن کے بچوں اور گاد کے بچوں سے گلعاد کی سرزمین سے کنعان کی زمین، بنی اسرائیل کے پاس واپس آئے اور انہیں دوبارہ خبر دی۔ \n33۔ اور یہ بات بنی اسرائیل کو پسند آئی؛ اور بنی اسرائیل نے خدا کو برکت دی، اور جنگ میں ان کے خلاف جانے کا ارادہ نہیں کیا، تاکہ اس زمین کو تباہ کریں جہاں روبن اور گاد کے بچے رہتے تھے۔ \n34۔ اور روبن کے بچوں اور گاد کے بچوں نے قربان گاہ کو بلایا: کیونکہ یہ ہمارے درمیان گواہی ہوگی کہ خداوند خدا ہے۔ یعنی، گواہ","1۔ اور بہت عرصہ بعد جب خداوند نے اسرائیل کو ان کے تمام دشمنوں سے سکون دیا، تب یشوع بوڑھا ہو گیا {اور} بوڑھا ہو گیا۔ {متاثر ہوئے...: عبرانی۔ دنوں میں آؤ}\n2۔ اور یشوع نے تمام اسرائیل، {اور} ان کے بزرگوں، ان کے سروں، ان کے قاضوں اور ان کے افسران کو بلایا، اور ان سے کہا، میں بوڑھا ہوں {اور} بوڑھا ہو چکا ہوں: \n3۔ اور تم نے وہ سب کچھ دیکھا ہے جو خداوند تمہارے خدا نے ان تمام قوموں کے ساتھ تمہاری وجہ سے کیا؛ کیونکہ خداوند تمہارا خدا وہی ہے جو تمہارے لیے لڑا۔ \n4۔ دیکھو، میں نے تم پر یہ قومیں قرعہ ڈال کر تقسیم کر دی ہیں، جو تمہارے قبائل کے لیے وراثت ہیں، اردن سے، ان تمام قوموں کے ساتھ جنہیں میں نے کاٹ دیا ہے، یہاں تک کہ عظیم سمندر تک مغرب کی طرف۔ {مغرب کی طرف: عبرانی۔ غروب آفتاب پر}\n5۔ اور خداوند تمہارا خدا، وہ انہیں تمہارے سامنے سے نکال دے گا اور تمہاری نظر سے دور کر دے گا؛ اور تم ان کی زمین پر قبضہ کرو گے، جیسا کہ خداوند تمہارے خدا نے تمہیں وعدہ کیا ہے۔ \n6۔ لہٰذا تم بہت بہادر رہو کہ موسیٰ کی شریعت کی کتاب میں جو کچھ بھی لکھا ہے اسے پورا کرو اور عمل کرو، تاکہ تم اس سے نہ منہ موڑو نہ دائیں ہاتھ اور نہ ہی بائیں ہاتھ کو؛ \n7۔ کہ تم ان قوموں میں نہ آؤ، جو تمہارے درمیان رہ گئے ہیں؛ نہ ان کے دیوتاؤں کا نام لینا، نہ ان کی قسم کھاؤ، نہ ان کی عبادت کرو، نہ ان کے سامنے سجدہ کرو۔ \n8. لیکن اپنے خداوند خدا سے چمٹ جاؤ، جیسا کہ تم آج تک کرتے آئے ہو۔ {لیکن پھٹ جاؤ...: یا، اگر تم چاہو تو، وغیرہ}\n9۔ کیونکہ خداوند نے آپ کے سامنے سے عظیم اور طاقتور قوموں کو نکال دیا ہے: لیکن {جہاں تک} آپ کے لیے ہے، آج تک کوئی انسان آپ کے سامنے کھڑا نہیں ہو سکا۔ {خداوند کے لیے...: یا، پھر خداوند چلائے گا}\n10۔ تم میں سے ایک آدمی ہزار کا پیچھا کرے گا: خداوند تمہارا خدا ہے جو تمہارے لیے لڑتا ہے، جیسا کہ اس نے تم سے وعدہ کیا ہے۔ \n11۔ اس لیے اپنے آپ سے اچھی طرح ہوشیار رہو، کہ تم اپنے خداوند اپنے خدا سے محبت کرتے ہو۔ {تم لوگ: عبرانی۔ تمہاری جانیں}\n12۔ ورنہ اگر تم کسی بھی طرح واپس جاؤ اور ان قوموں کے باقیات سے چمٹ جاؤ، حتیٰ کہ جو تم میں باقی رہ گئے ہیں، ان سے شادی کرو، اور ان کے پاس جاؤ، اور وہ بھی تمہارے ساتھ: \n13۔ یقین رکھو کہ خداوند تمہارا خدا اب ان قوموں کو تمہارے سامنے سے نہیں نکالے گا؛ بلکہ وہ تمہارے لیے جال اور جال ہوں گے، تمہارے پہلوؤں میں کوڑے ہوں گے، اور تمہاری آنکھوں میں کانٹے ہوں گے، یہاں تک کہ تم اس نیک زمین سے فنا ہو جاؤ جو خداوند تمہارے خدا نے تمہیں دی ہے۔ \n14۔ اور دیکھو، آج میں {آگے} پوری زمین کی راہ پر چل رہا ہوں: اور تم اپنے تمام دلوں اور اپنی تمام روحوں میں جانتے ہو کہ خداوند تمہارے خدا کی تمہارے بارے میں کہی گئی تمام اچھی باتوں میں سے ایک بھی چیز ناکام نہیں ہوئی؛ سب کچھ تمہارے لیے انجام دیا گیا ہے، {اور} ایک بھی چیز ناکام نہیں ہوئی۔ \n15۔ لہٰذا یہ ہو جائے گا، {کہ} جیسے تم پر تمام اچھائیاں آتی ہیں، جو خداوند تمہارے خدا نے تمہیں وعدہ کیا ہے؛ اسی طرح خداوند تم پر تمام برائیاں نازل کرے گا، یہاں تک کہ وہ تمہیں اس نیک زمین سے تباہ کر دے جو خداوند تمہارے خدا نے تمہیں دی ہے۔ \n16۔ جب آپ خداوند آپ کے خدا کے عہد کی خلاف ورزی کریں گے، جس کا اس نے آپ کو حکم دیا تھا، اور دوسرے دیوتاؤں کی عبادت کر کے ان کے سامنے جھک گئے؛ تب آپ پر خداوند کا غصہ بھڑک اٹھے گا، اور آپ اس نیک زمین سے جلدی فنا ہو جائیں گے جو اس نے آپ کو دی ہے۔","1۔ اور یشوع نے اسرائیل کے تمام قبائل کو شکم میں جمع کیا، اور اسرائیل کے بزرگوں، ان کے سروں، ان کے قاضیوں اور ان کے افسران کو بلایا؛ اور وہ خدا کے سامنے پیش ہوئے۔ \n2۔ اور یشوع نے سب لوگوں سے کہا، یوں اسرائیل کے خداوند خدا نے فرمایا، تیرہ آباؤ اجداد بھی پرانے زمانے میں سیلاب کے دوسری طرف رہتے تھے، حتیٰ کہ تارح، ابراہیم کا باپ، اور ناخور کا باپ: اور وہ دوسرے دیوتاؤں کی عبادت کرتے تھے۔ \n3۔ اور میں نے تمہارے والد ابراہیم کو سیلاب کے دوسری طرف سے اٹھایا، اسے پورے کنعان کی سرزمین میں لے گیا، اس کی نسل کو بڑھا دیا اور اسے اسحاق دیا۔ \n4۔ اور میں نے اسحاق یعقوب اور عیسو کو دیا: اور میں نے عیسو کو کوہ سعیر کو دیا، تاکہ وہ اسے حاصل کرے؛ لیکن یعقوب اور اس کے بچے مصر میں اتر گئے۔ \n5۔ میں نے موسیٰ اور ہارون کو بھی بھیجا، اور میں نے مصر کو تنگ کیا، جیسا کہ میں نے ان کے درمیان کیا، اور بعد میں تمہیں باہر نکالا۔ \n6۔ اور میں نے تمہارے باپ اجداد کو مصر سے نکالا: اور تم سمندر پر آئے؛ اور مصری تمہارے آباؤ اجداد کے پیچھے رتھ اور گھڑ سواروں کے ساتھ بحیرہ احمر تک گئے۔ \n7۔ اور جب انہوں نے خداوند کو پکارا، تو اس نے تم اور مصریوں کے درمیان تاریکی ڈال دی، سمندر ان پر لے آیا اور انہیں ڈھانپ دیا؛ اور تمہاری آنکھوں نے دیکھا کہ میں نے مصر میں کیا کیا، اور تم طویل عرصے تک بیابان میں رہے۔ \n8۔ اور میں نے تمہیں اموریوں کی سرزمین میں لے آیا، جو اردن کے دوسری طرف رہتے تھے؛ اور وہ تم سے لڑے، اور میں نے انہیں تمہارے ہاتھ میں دے دیا، تاکہ تم ان کی زمین پر قبضہ کر سکو؛ اور میں نے انہیں تمہارے سامنے سے تباہ کر دیا۔ \n9۔ پھر موآب کے بادشاہ زیپور کے بیٹے بالک اٹھا اور اسرائیل کے خلاف جنگ کی، اور بیور کے بیٹے بلعام کو بلایا تاکہ تم پر لعنت کرے: \n10۔ لیکن میں نے بلعام کی بات نہیں مانی؛ اس لیے اس نے تمہیں پھر بھی برکت دی: یوں میں نے تمہیں اس کے ہاتھوں سے آزاد کر دیا۔ \n11۔ اور تم اردن کے پار گئے، اور یریحو آئے: اور یریحو کے لوگ تم سے لڑے، اموریوں، پیریزوں، کنعانیوں کے خلاف، حتیوں، گرگاشیوں، حویوں، اور یبوسی لوگوں کے خلاف؛ اور میں نے انہیں تمہارے ہاتھ میں دے دیا۔ \n12۔ اور میں نے تمہارے سامنے کو بھیجا، جس نے انہیں تمہارے سامنے سے نکال دیا، حتیٰ کہ اموریوں کے دو بادشاہوں کو بھی؛ {لیکن} نہ اپنی تلوار سے، نہ اپنی کمان سے۔ \n13۔ اور میں نے تمہیں وہ زمین دی ہے جس کے لیے تم نے محنت نہیں کی، اور شہر جو تم نے نہیں بنائے، اور تم ان میں رہتے ہو؛ ان انگور اور زیتونوں کے باغات جو تم نے لگائے ہیں اور نہیں کھاتے۔ \n14۔ اب خداوند سے ڈرو، اور اس کی خلوص اور سچائی سے خدمت کرو: اور ان دیوتاؤں کو چھوڑ دو جن کی خدمت تمہارے آباؤ اجداد نے سیلاب کے دوسری طرف اور مصر میں کی تھی؛ اور خداوند کی عبادت کرو۔ \n15۔ اور اگر تمہیں خدا کی عبادت کرنا برا لگے، تو آج خود کو منتخب کرو کہ تم کس کی عبادت کرو گے؛ چاہے وہ خدا جن کی تمہارے باپ اجداد نے عبادت کی جو سیلاب کے دوسری طرف تھے، یا اموری کے دیوتا، جن کی سرزمین میں تم رہتے ہو؛ لیکن جہاں تک میں اور میرے گھرانے کا تعلق ہے، ہم خداوند کی عبادت کریں گے۔ \n16۔ اور لوگوں نے جواب دیا اور کہا، خدا نہ کرے کہ ہم خداوند کو چھوڑ کر دوسرے دیوتاؤں کی عبادت کریں؛ \n17۔ خداوند ہمارے خدا کے لیے، وہی ہے جس نے ہمیں اور ہمارے باپ اجداد کو مصر کی سرزمین سے، غلامی کے گھر سے نکالا، اور جس نے ہمارے سامنے وہ عظیم نشانیاں دکھائیں، اور ہمیں ہر راستے میں محفوظ رکھا جہاں ہم گئے، اور ان تمام لوگوں میں جن سے ہم گزرے: \n18۔ اور خداوند نے ہمارے سامنے سے تمام لوگوں کو، حتیٰ کہ وہ اموریوں کو بھی نکال دیا جو زمین میں بستے تھے: {لہٰذا} ہم بھی خداوند کی عبادت کریں گے؛ کیونکہ وہ ہمارا خدا ہے۔ \n19۔ اور یشوع نے لوگوں سے کہا، تم خداوند کی عبادت نہیں کر سکتے: کیونکہ وہ ایک مقدس خدا ہے؛ وہ حسد کرنے والا خدا ہے؛ وہ تمہاری گناہوں اور گناہوں کو معاف نہیں کرے گا۔ {پاک خدا: عبرانی۔ مقدس خدا}\n20۔ اگر آپ خداوند کو چھوڑ کر اجنبی دیوتاؤں کی عبادت کریں، تو وہ آپ کو نقصان پہنچائے گا، اور آپ کو نگل جائے گا، اس کے بعد اس نے آپ کے لیے اچھا کیا۔ \n21۔ اور لوگوں نے یشوع سے کہا، نہیں؛ لیکن ہم خداوند کی خدمت کریں گے۔ \n22۔ اور یشوع نے لوگوں سے کہا، تم اپنے خلاف گواہ ہو کہ تم نے خود کو خداوند منتخب کیا ہے، تاکہ وہ اس کی خدمت کرے۔ اور انہوں نے کہا، {ہم} گواہ ہیں۔ \n23. لہٰذا، اس نے کہا، ان عجیب دیوتاؤں کو چھوڑ دو جو تمہارے درمیان ہیں، اور اپنا دل اسرائیل کے خداوند خدا کی طرف جھکاؤ۔ \n24۔ اور لوگوں نے یشوع سے کہا، خداوند ہمارا خدا ہے جس کی ہم عبادت کریں گے، اور اس کی آواز کی ہم اطاعت کریں گے۔ \n25۔ تو یشوع نے اسی دن لوگوں سے ایک عہد کیا، اور انہیں شیکم میں ایک قانون اور فرمان مقرر کیا۔ \n26۔ اور یشوع نے یہ الفاظ خدا کے قانون کی کتاب میں لکھے، اور ایک بڑا پتھر اٹھا کر وہاں ایک بلوط کے نیچے رکھ دیا، جو خداوند کے مقدس مقام کے پاس تھا۔ \n27۔ اور یشوع نے سب لوگوں سے کہا، دیکھو، یہ پتھر ہمارے لیے گواہ ہوگا؛ کیونکہ اس نے خداوند کے تمام الفاظ سن لیے ہیں جو اس نے ہم سے کہے: اس لیے یہ تمہارے لیے گواہ بنے گا، ورنہ تم اپنے خدا کا انکار کرو۔ \n28۔ تو یشوع نے لوگوں کو روانہ کیا، ہر آدمی اپنی میراث کے لیے۔ \n29۔ اور ان واقعات کے بعد ہوا کہ یشوع، نون کا بیٹا، خداوند کا بندہ، فوت ہو گیا، اور وہ سو دس سال کا تھا۔ \n30۔ اور انہوں نے اسے اس کی وراثت کی سرحد پر تیمناثسرہ میں دفن کیا، جو افریم پہاڑ میں واقع ہے، گاش کی پہاڑی کے شمالی جانب۔ \n31۔ اور اسرائیل نے خداوند کی خدمت یشوع کے تمام دنوں اور ان بزرگوں کی بھی خدمت کی جو یشوع سے زیادہ زندہ رہے، اور جنہوں نے خداوند کے تمام اعمال جانتے تھے جو اس نے اسرائیل کے لیے کیے تھے۔ {زیادہ زندہ رہا...: عبرانی۔ یشوع کے بعد ان کے دن طول دیے}\n32۔ اور یوسف کی ہڈیاں، جو بنی اسرائیل نے مصر سے لائی، انہوں نے شیکم میں دفن کی، ایک زمین کے ٹکڑے میں جو یعقوب نے حمور کے بیٹوں سے سو چاندی کے ٹکڑوں میں خریدا تھا، اور یہ یوسف کے بچوں کی وراثت بن گئی۔ {ٹکڑے...: یا، بکر}\n33۔ اور الیعزر، ہارون کا بیٹا، مر گیا؛ اور اسے ایک پہاڑی میں دفن کیا گیا جو اس کا بیٹا فینیحاس سے متعلق تھا، جو اسے کوہ افرایم میں دیا گیا تھا۔"];
